import type { WisdomArticle } from "./types";
import { educationImages, eduImage } from "./education-images";

/** Articles sourced verbatim from temp-content/p3.txt (link-scrubbed, headings normalized) */
export const p3Articles: WisdomArticle[] = [
  {
    id: "western-differences",
    section: "introduction",
    title: { en: `Vedic and Western Astrology: Key Differences`, hi: `वैदिक और पश्चिमी ज्योतिष: मुख्य अंतर`, ja: `ヴェーダ占星術と西洋占星術: 主な違い`, ko: `베다 점성술과 서양 점성술: 주요 차이점`,},
    related: ["paradigm-shift","sidereal-zodiac-p3","faqs-2"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Vedic and Western Astrology: Key Differences`, hi: `वैदिक और पश्चिमी ज्योतिष: मुख्य अंतर`, ja: `ヴェーダ占星術と西洋占星術: 主な違い`, ko: `베다 점성술과 서양 점성술: 주요 차이점`,} },
      { type: "paragraph", text: { en: `Summary: This article explores the major differences between Vedic Astrology and Western Astrology. The Vedic system differs significantly from the Western approach in its origins (through Vedic cognition), underlying paradigms (predictive, preventive, karmic, and based on coded information rather than planetary forces), and methodology (including the use of only nine planets, the sidereal zodiac, functional benefics, Mahadasha timing systems, and more).`, hi: `सारांश: यह लेख वैदिक ज्योतिष और पश्चिमी ज्योतिष के बीच प्रमुख अंतरों की पड़ताल करता है। वैदिक प्रणाली अपनी उत्पत्ति (वैदिक अनुभूति के माध्यम से), अंतर्निहित प्रतिमानों (भविष्यवाणी, निवारक, कर्म और ग्रहों की ताकतों के बजाय कोडित जानकारी पर आधारित) और कार्यप्रणाली (केवल नौ ग्रहों का उपयोग, नक्षत्र राशि चक्र, कार्यात्मक लाभ, महादशा समय प्रणाली, और अधिक) में पश्चिमी दृष्टिकोण से काफी भिन्न है।`, ja: `概要: この記事では、ヴェーダ占星術と西洋占星術の主な違いについて説明します。ヴェーダのシステムは、その起源（ヴェーダの認識による）、基礎となるパラダイム（予測、予防、カルマ、惑星の力ではなくコード化された情報に基づく）、および方法論（わずか9つの惑星の使用、恒星黄道帯、機能的恩恵、マハダシャータイミングシステムなどを含む）において、西洋のアプローチとは大きく異なります。`, ko: `요약: 이 기사에서는 베다 점성술과 서양 점성술의 주요 차이점을 살펴봅니다. 베다 시스템은 기원(베다 인식을 통해), 기본 패러다임(예측, 예방, 카르마, 행성의 힘이 아닌 암호화된 정보 기반) 및 방법론(9개의 행성만 사용, 항성 황도대, 기능적 혜택, 마하다샤 타이밍 시스템 등 포함)에서 서양 접근 방식과 크게 다릅니다.`,} },
      { type: "heading", level: 3, text: { en: `Different Systems – Different Strengths`, hi: `अलग-अलग प्रणालियाँ - अलग-अलग ताकतें`, ja: `異なるシステム – 異なる強み`, ko: `다양한 시스템 – 다양한 강점`,} },
      { type: "paragraph", text: { en: `When we examine both Vedic Astrology and Western Astrology, it becomes clear that each system possesses its own unique strengths.`, hi: `जब हम वैदिक ज्योतिष और पश्चिमी ज्योतिष दोनों की जांच करते हैं, तो यह स्पष्ट हो जाता है कि प्रत्येक प्रणाली की अपनी अनूठी ताकत होती है।`, ja: `ヴェーダ占星術と西洋占星術の両方を調べると、それぞれの体系が独自の強みを持っていることが明らかになります。`, ko: `베다 점성술과 서양 점성술을 모두 살펴보면 각 시스템이 고유한 장점을 가지고 있다는 것이 분명해집니다.`,} },
      { type: "paragraph", text: { en: `Western Astrology generally places greater emphasis on psychology and the workings of the mind. As a result, a Western birth chart can provide an excellent foundation for counselling and self-reflection. For those seeking deeper understanding of their thoughts, emotions, and inner psychological nature, Western Astrology offers valuable insights.`, hi: `पश्चिमी ज्योतिष आमतौर पर मनोविज्ञान और मन की कार्यप्रणाली पर अधिक जोर देता है। परिणामस्वरूप, एक पश्चिमी जन्म कुंडली परामर्श और आत्म-चिंतन के लिए एक उत्कृष्ट आधार प्रदान कर सकती है। अपने विचारों, भावनाओं और आंतरिक मनोवैज्ञानिक प्रकृति की गहरी समझ चाहने वालों के लिए, पश्चिमी ज्योतिष मूल्यवान अंतर्दृष्टि प्रदान करता है।`, ja: `西洋占星術は一般的に心理学や心の働きに重点を置きます。その結果、西洋出生図はカウンセリングと内省のための優れた基盤となります。自分の思考、感情、内なる心理的性質をより深く理解したい人にとって、西洋占星術は貴重な洞察を提供します。`, ko: `서양 점성술은 일반적으로 심리학과 마음의 작용을 더 강조합니다. 결과적으로 서양 출생 차트는 상담과 자기 성찰을 위한 훌륭한 기반을 제공할 수 있습니다. 자신의 생각, 감정, 내면의 심리적 본성에 대한 더 깊은 이해를 원하는 사람들에게 서양 점성술은 귀중한 통찰력을 제공합니다.`,} },
      { type: "paragraph", text: { en: `Vedic Astrology, by contrast, focuses more strongly on karma and the prediction of how karmic influences will unfold throughout life, including the timing of those events. It is distinctive in offering remedial measures designed to reduce or soften the impact of returning negative karmas. In this way, Vedic Astrology is both predictive and preventive, while also providing practical solutions to many of life's challenges.`, hi: `इसके विपरीत, वैदिक ज्योतिष कर्म पर अधिक दृढ़ता से ध्यान केंद्रित करता है और भविष्यवाणी करता है कि कर्म प्रभाव पूरे जीवन में कैसे प्रकट होंगे, जिसमें उन घटनाओं का समय भी शामिल है। यह नकारात्मक कर्मों के प्रभाव को कम करने या नरम करने के लिए डिज़ाइन किए गए उपचारात्मक उपायों की पेशकश करने में विशिष्ट है। इस प्रकार, वैदिक ज्योतिष भविष्यसूचक और निवारक दोनों है, साथ ही जीवन की कई चुनौतियों का व्यावहारिक समाधान भी प्रदान करता है।`, ja: `対照的に、ヴェーダ占星術は、カルマと、その出来事のタイミングを含め、カルマの影響が生涯を通じてどのように展開するかという予測に、より重点を置いています。ネガティブなカルマを返すことによる影響を軽減または和らげることを目的とした是正措置を提供することが特徴です。このように、ヴェーダ占星術は予測的かつ予防的であると同時に、人生の課題の多くに対する実用的な解決策も提供します。`, ko: `이와 대조적으로 베다 점성술은 카르마와 카르마의 영향이 일생 동안 어떻게 전개될지에 대한 예측(해당 사건의 시기 포함)에 더욱 중점을 둡니다. 부정적인 카르마 반환의 영향을 줄이거 나 완화하기 위해 고안된 교정 조치를 제공하는 것이 특징입니다. 이러한 방식으로 베다 점성술은 예측과 예방을 동시에 수행하는 동시에 삶의 많은 문제에 대한 실질적인 해결책을 제공합니다.`,} },
      { type: "paragraph", text: { en: `While these observations are broad generalizations—and astrologers from both traditions would no doubt enjoy debating them—they help illustrate the different areas of emphasis within Western and Vedic Astrology.`, hi: `हालांकि ये अवलोकन व्यापक सामान्यीकरण हैं - और दोनों परंपराओं के ज्योतिषियों को निस्संदेह उन पर बहस करने में आनंद आएगा - वे पश्चिमी और वैदिक ज्योतिष के भीतर जोर के विभिन्न क्षेत्रों को चित्रित करने में मदद करते हैं।`, ja: `これらの観察は広範な一般化ですが、両方の伝統を持つ占星術師は間違いなくそれらについての議論を楽しんでいますが、西洋占星術とヴェーダ占星術の中で重点が置かれているさまざまな領域を説明するのに役立ちます。`, ko: `이러한 관찰은 광범위한 일반화이며 두 전통의 점성가들은 의심할 바 없이 이에 대해 토론하는 것을 좋아할 것입니다. 이는 서양 점성술과 베다 점성술 내에서 강조되는 다양한 영역을 설명하는 데 도움이 됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Vedic Astrology – Predictive and Preventive`, hi: `वैदिक ज्योतिष - भविष्य कहनेवाला और निवारक`, ja: `ヴェーダ占星術 – 予測と予防`, ko: `베다 점성술 - 예측 및 예방`,} },
      { type: "paragraph", text: { en: `Jyotish is fundamentally predictive. It identifies potential opportunities and obstacles across all major areas of life, including health, home, wealth, income, children, career, relationships, and spiritual development.[1] It forecasts both favorable periods and more challenging phases that may arise in the future. In doing so, it seeks to identify returning karmas and determine when they are most likely to manifest.`, hi: `ज्योतिष मूलतः भविष्यसूचक है। यह स्वास्थ्य, घर, धन, आय, बच्चे, करियर, रिश्ते और आध्यात्मिक विकास सहित जीवन के सभी प्रमुख क्षेत्रों में संभावित अवसरों और बाधाओं की पहचान करता है।[1] यह भविष्य में उत्पन्न होने वाली अनुकूल अवधियों और अधिक चुनौतीपूर्ण चरणों दोनों का पूर्वानुमान लगाता है। ऐसा करने में, यह लौटने वाले कर्मों की पहचान करने और यह निर्धारित करने का प्रयास करता है कि उनके प्रकट होने की सबसे अधिक संभावना कब है।`, ja: `ジョーティッシュは基本的に予測的です。これは、健康、家庭、富、収入、子供、キャリア、人間関係、精神的発達など、人生の主要な分野すべてにわたって潜在的な機会と障害を特定します[1]。好調な時期と、将来起こる可能性のあるより困難な局面の両方を予測します。そうすることで、戻ってくるカルマを特定し、それがいつ現れる可能性が最も高いかを判断しようとします。`, ko: `Jyotish는 근본적으로 예측 가능합니다. 건강, 가정, 부, 소득, 자녀, 직업, 인간관계, 영적 발전 등 삶의 모든 주요 영역에서 잠재적인 기회와 장애물을 식별합니다.[1] 이는 미래에 발생할 수 있는 유리한 시기와 보다 어려운 시기를 모두 예측합니다. 그렇게 함으로써, 되돌아오는 카르마를 식별하고 카르마가 나타날 가능성이 가장 높은 시기를 결정하려고 합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish is also preventive. It employs a wide range of remedial measures intended to influence an individual's returning karma. This ability to prescribe remedies that help rebalance planetary energies, as revealed in the birth chart, is one of the unique characteristics of Jyotish. At its core, Vedic Astrology can therefore be viewed as a form of karmic engineering.`, hi: `ज्योतिष निवारक भी है. यह किसी व्यक्ति के रिटर्निंग कर्म को प्रभावित करने के उद्देश्य से उपचारात्मक उपायों की एक विस्तृत श्रृंखला को नियोजित करता है। ग्रहों की ऊर्जा को पुनर्संतुलित करने में मदद करने वाले उपचारों को निर्धारित करने की यह क्षमता, जैसा कि जन्म कुंडली में बताया गया है, ज्योतिष की अनूठी विशेषताओं में से एक है। इसके मूल में, वैदिक ज्योतिष को कार्मिक इंजीनियरिंग के एक रूप के रूप में देखा जा सकता है।`, ja: `ジョーティッシュは予防効果もあります。個人の戻ってきたカルマに影響を与えることを目的とした幅広い是正措置を採用しています。出生図で明らかなように、惑星のエネルギーのバランスを取り戻すのに役立つ治療法を処方する能力は、ジョーティッシュのユニークな特徴の 1 つです。したがって、本質的には、ヴェーダ占星術はカルマ工学の一形態として見ることができます。`, ko: `Jyotish는 또한 예방적입니다. 이는 개인의 카르마 복귀에 영향을 미치기 위해 광범위한 교정 조치를 사용합니다. 출생 차트에 나타난 것처럼 행성 에너지의 균형을 재조정하는 데 도움이 되는 치료법을 처방하는 능력은 Jyotish의 독특한 특징 중 하나입니다. 그러므로 베다 점성술의 핵심은 카르마 공학의 한 형태로 볼 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Jyotish additionally includes techniques for determining the most favorable timing for important activities such as starting a business, getting married, building a home, or undertaking other major ventures. This branch of astrology is known as Muhurta. As the saying goes, "Well begun is half done."`, hi: `ज्योतिष में व्यवसाय शुरू करने, शादी करने, घर बनाने या अन्य प्रमुख उद्यम शुरू करने जैसी महत्वपूर्ण गतिविधियों के लिए सबसे अनुकूल समय निर्धारित करने की तकनीकें भी शामिल हैं। ज्योतिष की इस शाखा को मुहूर्त के नाम से जाना जाता है। जैसा कि कहा जाता है, "अच्छी शुरुआत तो आधी हो जाती है।"`, ja: `さらに、Jyotish には、起業、結婚、住宅建設、その他の大きな事業への取り組みなど、重要な活動に最も有利なタイミングを判断するためのテクニックも含まれています。この占星術の分野はムフルタとして知られています。ことわざにあるように、「始まったものは半分終わったもの」です。`, ko: `Jyotish에는 사업 시작, 결혼, 주택 건설 또는 기타 주요 사업 수행과 같은 중요한 활동에 가장 유리한 시기를 결정하는 기술도 포함되어 있습니다. 이 점성술 분야는 무후르타(Muhurta)로 알려져 있습니다. "시작이 반이다"라는 말이 있듯이요.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish Astrology: Cognized – Not Developed`, hi: `ज्योतिष: ज्ञात - विकसित नहीं`, ja: `ジョーティッシュ: 認識されているが発展していない`, ko: `Jyotish 점성술: 인식 – 개발되지 않음`,} },
      { type: "paragraph", text: { en: `Unlike Western Astrology, which evolved through centuries of human development and refinement, Jyotish was cognized. According to Vedic understanding, a great seer or Rishi—in this case Maharishi Parashara—connected individual consciousness with the universal field of intelligence and "downloaded" the complete knowledge and techniques of Vedic Astrology.`, hi: `पश्चिमी ज्योतिष के विपरीत, जो सदियों के मानव विकास और परिष्कार के माध्यम से विकसित हुआ, ज्योतिष को मान्यता दी गई थी। वैदिक समझ के अनुसार, एक महान द्रष्टा या ऋषि - इस मामले में महर्षि पराशर - ने व्यक्तिगत चेतना को बुद्धि के सार्वभौमिक क्षेत्र से जोड़ा और वैदिक ज्योतिष का संपूर्ण ज्ञान और तकनीक "डाउनलोड" की।`, ja: `何世紀にもわたる人類の発達と洗練を通じて進化した西洋占星術とは異なり、ジョーティッシュは認識されました。ヴェーダの理解によれば、偉大な先見者またはリシ、この場合はマハリシ・パラシャラが、個人の意識を普遍的な知性の領域に結び付け、ヴェーダ占星術の完全な知識と技術を「ダウンロード」しました。`, ko: `수세기에 걸쳐 인간의 발달과 개선을 통해 발전한 서양 점성술과 달리 Jyotish는 인식되었습니다. 베다 이해에 따르면, 위대한 선견자 또는 리시(이 경우에는 마하리시 파라샤라)는 개인의 의식을 보편적 지능 분야와 연결하고 베다 점성술의 완전한 지식과 기술을 "다운로드"했습니다.`,} },
      { type: "paragraph", text: { en: `For this reason, Jyotish Astrologers regard their discipline with deep respect, viewing it as a divine gift intended to help reduce human suffering.`, hi: `इस कारण से, ज्योतिषी अपने अनुशासन को गहरे सम्मान के साथ मानते हैं, इसे मानवीय पीड़ा को कम करने में मदद करने के लिए एक दिव्य उपहार के रूप में देखते हैं।`, ja: `このため、ジョーティッシュ師は自分たちの規律を深い敬意を持って捉えており、それを人間の苦しみを軽減することを目的とした神からの贈り物であるとみなしています。`, ko: `이러한 이유로 Jyotish 점성가들은 그들의 규율을 깊은 존경심으로 여기며 이를 인간의 고통을 줄이는 데 도움이 되는 신성한 선물로 간주합니다.`,} },
      { type: "paragraph", text: { en: `Vedic Astrology originates from the same ancient tradition that gave rise to Yoga, Meditation, Pranayama, Ayurveda, and Vastu.`, hi: `वैदिक ज्योतिष उसी प्राचीन परंपरा से उत्पन्न हुआ है जिसने योग, ध्यान, प्राणायाम, आयुर्वेद और वास्तु को जन्म दिया।`, ja: `ヴェーダ占星術は、ヨガ、瞑想、プラナヤマ、アーユルヴェーダ、ヴァストゥを生み出したのと同じ古代の伝統に由来しています。`, ko: `베다 점성술은 요가, 명상, 프라나야마, 아유르베다, 바스투를 탄생시킨 동일한 고대 전통에서 유래합니다.`,} },
      { type: "heading", level: 3, text: { en: `Vedic Astrology Only Needs to Use Nine ‘Planets’`, hi: `वैदिक ज्योतिष में केवल नौ 'ग्रहों' का उपयोग करने की आवश्यकता है`, ja: `ヴェーダ占星術は9つの「惑星」だけを使用する必要があります`, ko: `베다 점성술은 9개의 '행성'만 사용해야 합니다.`,} },
      { type: "paragraph", text: { en: `Traditional Jyotish uses only nine Grahas—commonly translated as the nine "planets." These consist of the seven visible planets up to Saturn, along with the two lunar nodes. Unlike Western Astrology, it does not incorporate the planets beyond Saturn because it simply has no need to do so.`, hi: `पारंपरिक ज्योतिष केवल नौ ग्रह का उपयोग करता है - जिसे आमतौर पर नौ "ग्रह" के रूप में अनुवादित किया जाता है। इनमें दो चंद्र नोड्स के साथ-साथ शनि तक सात दृश्यमान ग्रह शामिल हैं। पश्चिमी ज्योतिष के विपरीत, इसमें शनि से परे के ग्रहों को शामिल नहीं किया गया है क्योंकि ऐसा करने की कोई आवश्यकता ही नहीं है।`, ja: `伝統的なジョーティッシュでは、一般に 9 つの「惑星」と訳される 9 つのグラハのみを使用します。これらは、土星までの 7 つの目に見える惑星と 2 つの月のノードで構成されています。西洋占星術とは異なり、土星以降の惑星は組み込まれていません。単にそうする必要がないからです。`, ko: `전통적인 Jyotish에서는 일반적으로 9개의 "행성"으로 번역되는 9개의 Grahas만 사용합니다. 이는 두 개의 달 노드와 함께 토성까지 보이는 7개의 행성으로 구성됩니다. 서양 점성술과 달리 토성 너머의 행성은 포함하지 않습니다. 왜냐하면 단순히 그렇게 할 필요가 없기 때문입니다.`,} },
      { type: "paragraph", text: { en: `In Vedic Astrology, all the information required for prediction is encoded within the arrangement of these nine planets at the moment of birth. The later movement of planets through transit generally carries less predictive weight.`, hi: `वैदिक ज्योतिष में, भविष्यवाणी के लिए आवश्यक सभी जानकारी जन्म के समय इन नौ ग्रहों की व्यवस्था में समाहित होती है। गोचर के माध्यम से ग्रहों की बाद की गति आम तौर पर कम पूर्वानुमानित भार रखती है।`, ja: `ヴェーダ占星術では、予測に必要なすべての情報は、誕生の瞬間のこれら 9 つの惑星の配置内にコード化されています。太陽面通過による惑星のその後の動きは、一般に予測の重要性が低くなります。`, ko: `베다 점성술에서는 예측에 필요한 모든 정보가 탄생 순간에 이 9개 행성의 배열 내에 암호화되어 있습니다. 통과를 통한 행성의 이후 이동은 일반적으로 예측 가중치가 적습니다.`,} },
      { type: "paragraph", text: { en: `The positioning of the seven visible planets and the two lunar nodes among the twelve signs, twelve houses, and twenty-seven Nakshatras represents a highly sophisticated system of coded information. Likewise, planetary transits through signs and houses are interpreted as encoded information rather than as physical influences.`, hi: `बारह राशियों, बारह घरों और सत्ताईस नक्षत्रों के बीच सात दृश्य ग्रहों और दो चंद्र नोड्स की स्थिति कोडित जानकारी की एक अत्यधिक परिष्कृत प्रणाली का प्रतिनिधित्व करती है। इसी तरह, संकेतों और घरों के माध्यम से ग्रहों के गोचर की व्याख्या भौतिक प्रभावों के बजाय एन्कोडेड जानकारी के रूप में की जाती है।`, ja: `12 のサイン、12 ハウス、27 のナクシャトラにおける、目に見える 7 つの惑星と 2 つの月のノードの位置は、コード化された情報の高度に洗練されたシステムを表しています。同様に、標識やハウスを通過する惑星のトランジットは、物理的な影響としてではなく、コード化された情報として解釈されます。`, ko: `12개의 별자리, 12개의 집, 27개의 나크샤트라 사이에 보이는 7개의 행성과 2개의 달 노드의 위치는 매우 정교한 암호화된 정보 시스템을 나타냅니다. 마찬가지로 라시와 궁을 통한 행성 이동은 물리적 영향이 아닌 암호화된 정보로 해석됩니다.`,} },
      { type: "paragraph", text: { en: `If you encounter a "Jyotish Astrologer" who incorporates Uranus, Neptune, or Pluto, they are not practicing Traditional Jyotish Astrology but have instead blended elements from the two systems. Such an approach overlooks the fundamental concept of coded information.`, hi: `यदि आप किसी ऐसे "ज्योतिषी" से मिलते हैं जो यूरेनस, नेपच्यून या प्लूटो को शामिल करता है, तो वे पारंपरिक ज्योतिष का अभ्यास नहीं कर रहे हैं, बल्कि उन्होंने दो प्रणालियों के तत्वों को मिश्रित किया है। ऐसा दृष्टिकोण कोडित जानकारी की मूलभूत अवधारणा की अनदेखी करता है।`, ja: `天王星、海王星、冥王星を組み込んだ「ジョーティッシュ師」に出会った場合、彼らは伝統的なジョーティッシュを実践しているのではなく、代わりに 2 つのシステムの要素をブレンドしています。このようなアプローチでは、コード化された情報の基本的な概念が見落とされます。`, ko: `천왕성, 해왕성 또는 명왕성을 포함하는 "Jyotish 점성가"를 만난다면 그들은 전통적인 Jyotish 점성술을 수행하는 것이 아니라 대신 두 시스템의 요소를 혼합한 것입니다. 이러한 접근 방식은 코딩된 정보의 기본 개념을 간과합니다.`,} },
      { type: "paragraph", text: { en: `Because Vedic Astrology views the universe and all living beings as part of an interconnected field of energy, order, and intelligence, it works primarily with coded information.`, hi: `क्योंकि वैदिक ज्योतिष ब्रह्मांड और सभी जीवित प्राणियों को ऊर्जा, व्यवस्था और बुद्धि के एक परस्पर जुड़े क्षेत्र के हिस्से के रूप में देखता है, यह मुख्य रूप से कोडित जानकारी के साथ काम करता है।`, ja: `ヴェーダ占星術は、宇宙とすべての生き物をエネルギー、秩序、知性の相互接続された領域の一部と見なすため、主にコード化された情報を扱います。`, ko: `베다 점성술은 우주와 모든 생명체를 에너지, 질서, 지성의 상호 연결된 장의 일부로 보기 때문에 주로 암호화된 정보를 사용하여 작동합니다.`,} },
      { type: "paragraph", text: { en: `Western Astrology, on the other hand, is often more Newtonian and mechanistic in outlook. It tends to imply that planets emit some form of influence or force—yet to be identified by modern science—that affects human beings on Earth. Consequently, whenever astronomers discover a new celestial object within the solar system, Western Astrology must adapt and assign astrological meanings to that object.`, hi: `दूसरी ओर, पश्चिमी ज्योतिष अक्सर दृष्टिकोण में अधिक न्यूटोनियन और यंत्रवत होता है। इसका तात्पर्य यह है कि ग्रह किसी प्रकार का प्रभाव या बल उत्सर्जित करते हैं - जो आधुनिक विज्ञान द्वारा अभी तक पहचाना नहीं जा सका है - जो पृथ्वी पर मनुष्यों को प्रभावित करता है। नतीजतन, जब भी खगोलशास्त्री सौर मंडल के भीतर एक नई खगोलीय वस्तु की खोज करते हैं, तो पश्चिमी ज्योतिष को उस वस्तु को अनुकूलित और ज्योतिषीय अर्थ देना चाहिए।`, ja: `一方、西洋占星術は、多くの場合、よりニュートン的で機械的な見方をします。これは、惑星が地球上の人類に影響を与える、現代科学ではまだ特定されていない何らかの影響や力を発していることを暗示する傾向があります。したがって、天文学者が太陽系内で新しい天体を発見するたびに、西洋占星術はその天体に占星術的な意味を適応させて割り当てる必要があります。`, ko: `반면에 서양 점성술은 전망이 더 뉴턴적이고 기계론적입니다. 이는 행성이 지구상의 인간에게 영향을 미치는 어떤 형태의 영향이나 힘(아직 현대 과학에 의해 확인되지 않음)을 방출한다는 것을 암시하는 경향이 있습니다. 결과적으로, 천문학자들이 태양계 내에서 새로운 천체를 발견할 때마다 서양 점성술은 그 천체에 점성학적 의미를 적용하고 할당해야 합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish considers this unnecessary. It does not require the concept of planetary forces acting upon people. Instead, it interprets the coded information contained within planetary positions and configurations.`, hi: `ज्योतिष इसे अनावश्यक मानता है. इसमें लोगों पर कार्य करने वाली ग्रहीय शक्तियों की अवधारणा की आवश्यकता नहीं है। इसके बजाय, यह ग्रहों की स्थिति और विन्यास में निहित कोडित जानकारी की व्याख्या करता है।`, ja: `ジョーティッシュ氏はこれは不要だと考えている。人々に作用する惑星の力という概念は必要ありません。代わりに、惑星の位置と構成に含まれるコード化された情報を解釈します。`, ko: `Jyotish는 이것이 불필요하다고 생각합니다. 사람들에게 작용하는 행성의 힘에 대한 개념은 필요하지 않습니다. 대신, 행성의 위치와 구성에 포함된 암호화된 정보를 해석합니다.`,} },
      { type: "heading", level: 3, text: { en: `A Unique System of Time-Based Predictions – The Mahadashas`, hi: `समय-आधारित भविष्यवाणियों की एक अनूठी प्रणाली - महादशाएँ`, ja: `時間ベースの予測のユニークなシステム – マハダシャー`, ko: `독특한 시간 기반 예측 시스템 – Mahadashas`,} },
      { type: "paragraph", text: { en: `One of the most distinctive features of Jyotish is its Mahadasha system, which identifies major periods of karmic influence throughout life.`, hi: `ज्योतिष की सबसे विशिष्ट विशेषताओं में से एक इसकी महादशा प्रणाली है, जो जीवन भर कर्म प्रभाव की प्रमुख अवधियों की पहचान करती है।`, ja: `ジョーティッシュの最も特徴的な特徴の 1 つは、生涯を通じてカルマ的影響が大きく及んだ時期を特定するマハダシャ システムです。`, ko: `Jyotish의 가장 독특한 특징 중 하나는 일생 동안 카르마 영향의 주요 기간을 식별하는 Mahadasha 시스템입니다.`,} },
      { type: "paragraph", text: { en: `Like Western Astrology, Jyotish also considers planetary transits. However, in most cases, transits are far less significant than the Mahadashas when making predictions.`, hi: `पश्चिमी ज्योतिष की तरह ज्योतिष भी ग्रहों के गोचर पर विचार करता है। हालाँकि, अधिकांश मामलों में, भविष्यवाणियाँ करते समय पारगमन महादशाओं की तुलना में बहुत कम महत्वपूर्ण होते हैं।`, ja: `西洋占星術と同様に、ジョーティッシュも惑星の通過を考慮します。ただし、ほとんどの場合、予測を行う場合、トランジットはマハダシャーよりもはるかに重要ではありません。`, ko: `서양 점성술과 마찬가지로 Jyotish도 행성 이동을 고려합니다. 그러나 대부분의 경우 예측을 할 때 통과는 Mahadashas보다 훨씬 덜 중요합니다.`,} },
      { type: "paragraph", text: { en: `Mahadasha periods are essential for accurate forecasting. They allow the static factors represented by planetary placements in houses and signs to interact with the dynamic flow of time. This combination enables astrologers to determine both what is likely to happen and when it is likely to happen.`, hi: `सटीक पूर्वानुमान के लिए महादशा अवधि आवश्यक है। वे भावों और राशियों में ग्रहों की स्थिति द्वारा दर्शाए गए स्थिर कारकों को समय के गतिशील प्रवाह के साथ बातचीत करने की अनुमति देते हैं। यह संयोजन ज्योतिषियों को यह निर्धारित करने में सक्षम बनाता है कि क्या होने की संभावना है और कब होने की संभावना है।`, ja: `マハダシャー期間は正確な予測に不可欠です。これらにより、ハウスやラーシにおける惑星の配置によって表される静的な要素が、動的な時間の流れと相互作用することが可能になります。この組み合わせにより、占星術師は何が起こる可能性があるのか​​、またそれがいつ起こるのかを判断できるようになります。`, ko: `Mahadasha 기간은 정확한 예측을 위해 필수적입니다. 이를 통해 집과 표지판의 행성 배치로 표현되는 정적 요소가 시간의 역동적인 흐름과 상호 작용할 수 있습니다. 이 조합을 통해 점성가들은 일어날 가능성이 있는 일과 일어날 가능성이 있는 시기를 모두 결정할 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Ascendant of Key Importance in Jyotish`, hi: `ज्योतिष में प्रमुख महत्व का लग्न`, ja: `ジョーティッシュにおける重要なアセンダント`, ko: `Jyotish에서 중요한 중요성을 지닌 승천자`,} },
      { type: "paragraph", text: { en: `In Vedic Astrology, the Ascendant—the sign rising on the eastern horizon at the moment of birth—is of central importance. By comparison, the Sun sign emphasized in Western Astrology carries relatively little significance.`, hi: `वैदिक ज्योतिष में, लग्न - जन्म के समय पूर्वी क्षितिज पर उगने वाला चिन्ह - का केंद्रीय महत्व है। तुलनात्मक रूप से, पश्चिमी ज्योतिष में जिस सूर्य चिन्ह पर जोर दिया गया है उसका अपेक्षाकृत कम महत्व है।`, ja: `ヴェーダ占星術では、アセンダント (誕生の瞬間に東の地平線に昇る星座) が最も重要です。それに比べて、西洋占星術で強調される太陽星座は、比較的重要性が低いです。`, ko: `베다 점성술에서는 탄생 순간에 동쪽 지평선에 떠오르는 별자리인 승천이 가장 중요합니다. 이에 비해 서양 점성술에서 강조되는 태양궁은 상대적으로 중요성이 거의 없습니다.`,} },
      { type: "paragraph", text: { en: `The Ascendant plays a crucial role in determining suitable planetary remedies within Jyotish. It is also essential because it establishes which planets function as benefics and which act as malefics for a particular individual.`, hi: `ज्योतिष में उपयुक्त ग्रहीय उपाय निर्धारित करने में लग्न महत्वपूर्ण भूमिका निभाता है। यह इसलिए भी आवश्यक है क्योंकि यह स्थापित करता है कि कौन से ग्रह किसी व्यक्ति विशेष के लिए शुभ ग्रह के रूप में कार्य करते हैं और कौन से ग्रह अशुभ के रूप में कार्य करते हैं।`, ja: `アセンダントは、ジョーティッシュ内で適切な惑星のレメディーを決定する上で重要な役割を果たします。また、特定の個人にとってどの惑星が吉星として機能し、どの惑星が凶星として機能するかを確立するため、これは不可欠です。`, ko: `Ascendant는 Jyotish 내에서 적절한 행성 치료법을 결정하는 데 중요한 역할을 합니다. 또한 특정 개인에게 어떤 행성이 혜택으로 기능하고 어떤 행성이 흉성으로 작용하는지 확인하기 때문에 필수적입니다.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish Always Uses the Sidereal Zodiac`, hi: `ज्योतिष हमेशा नाक्षत्र राशि चक्र का उपयोग करता है`, ja: `ジョーティッシュは常に恒星星座を使用します`, ko: `Jyotish는 항상 항성 황도대를 사용합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish employs the same twelve zodiac signs used in Western Astrology. The difference lies in the reference point.`, hi: `ज्योतिष पश्चिमी ज्योतिष में प्रयुक्त उन्हीं बारह राशियों का उपयोग करता है। अंतर संदर्भ बिंदु में है.`, ja: `ジョーティッシュは、西洋占星術で使用されるのと同じ 12 の星座を使用します。違いは基準点にあります。`, ko: `Jyotish는 서양 점성술에서 사용되는 것과 동일한 12개의 황도대 별자리를 사용합니다. 차이점은 기준점에 있습니다.`,} },
      { type: "paragraph", text: { en: `In Jyotish, the zodiac is permanently aligned with the fixed stars and therefore remains stationary. This is known as the Sidereal Zodiac. Western Astrology, by contrast, generally uses the Tropical Zodiac, which gradually shifts over time.`, hi: `ज्योतिष में, राशि चक्र स्थायी रूप से स्थिर सितारों के साथ संरेखित होता है और इसलिए स्थिर रहता है। इसे नाक्षत्र राशि चक्र के नाम से जाना जाता है। इसके विपरीत, पश्चिमी ज्योतिष आम तौर पर उष्णकटिबंधीय राशि चक्र का उपयोग करता है, जो समय के साथ धीरे-धीरे बदलता रहता है।`, ja: `ジョーティッシュでは、黄道帯は永久に恒星と整列しているため、静止したままになります。これは恒星黄道帯として知られています。対照的に、西洋占星術では一般に、時間の経過とともに徐々に変化するトロピカル ゾディアックが使用されます。`, ko: `Jyotish에서는 황도대가 고정된 별과 영구적으로 정렬되므로 고정된 상태로 유지됩니다. 이것은 항성 황도대(Sidereal Zodiac)로 알려져 있습니다. 대조적으로, 서양 점성술은 일반적으로 시간이 지남에 따라 점차적으로 이동하는 열대 황도대를 사용합니다.`,} },
      { type: "paragraph", text: { en: `As a result, planetary positions are often different in the two systems, and planets may appear in different signs depending on which zodiac is being used.`, hi: `परिणामस्वरूप, दोनों प्रणालियों में ग्रहों की स्थिति अक्सर भिन्न होती है, और कौन सी राशि का उपयोग किया जा रहा है, उसके आधार पर ग्रह अलग-अलग राशियों में दिखाई दे सकते हैं।`, ja: `その結果、惑星の位置は 2 つの星系で異なることが多く、使用されている黄道帯に応じて惑星が異なる星座で表示される場合があります。`, ko: `결과적으로 행성의 위치는 두 시스템에서 서로 다른 경우가 많으며 어떤 황도대를 사용하는지에 따라 행성이 다른 별자리로 나타날 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Many Western Astrologers may find it surprising that the Tropical Zodiac is referenced to the moving equinox points rather than the fixed stars. Since these equinox points slowly shift relative to the background of the stars, the Tropical Zodiac itself gradually moves through the sky.`, hi: `कई पश्चिमी ज्योतिषियों को यह आश्चर्यजनक लग सकता है कि उष्णकटिबंधीय राशि चक्र को स्थिर तारों के बजाय गतिशील विषुव बिंदुओं से संदर्भित किया जाता है। चूँकि ये विषुव बिंदु धीरे-धीरे तारों की पृष्ठभूमि के सापेक्ष स्थानांतरित होते हैं, उष्णकटिबंधीय राशि चक्र स्वयं धीरे-धीरे आकाश में घूमता है।`, ja: `多くの西洋占星術師は、熱帯黄道帯が恒星ではなく移動する春分点に言及していることに驚くかもしれません。これらの春分点は星の背景に対してゆっくりと移動するため、熱帯黄道帯自体が空を徐々に移動します。`, ko: `많은 서양 점성가들은 열대 황도대가 고정된 별보다는 움직이는 춘분점을 참조한다는 사실이 놀랍다고 생각할 수도 있습니다. 이러한 분점은 별의 배경에 대해 천천히 이동하기 때문에 열대 황도대 자체는 하늘을 통해 점차적으로 이동합니다.`,} },
      { type: "paragraph", text: { en: `This means that the section of the zodiac called "Aries" in the Western system is not permanently tied to a specific stellar constellation. Over long periods, its position changes. The angular separation between the starting points of the Tropical and Sidereal zodiacs—currently around 24 degrees—is known as the Ayanamsha.`, hi: `इसका मतलब यह है कि राशि चक्र का वह भाग जिसे पश्चिमी प्रणाली में "मेष" कहा जाता है, स्थायी रूप से किसी विशिष्ट तारकीय नक्षत्र से बंधा नहीं है। लंबी अवधि में इसकी स्थिति बदलती रहती है। उष्णकटिबंधीय और नाक्षत्र राशियों के शुरुआती बिंदुओं के बीच कोणीय अलगाव - वर्तमान में लगभग 24 डिग्री - को अयनांश के रूप में जाना जाता है।`, ja: `これは、西洋のシステムで「牡羊座」と呼ばれる黄道帯のセクションが、特定の星座に永続的に関連付けられていないことを意味します。長期間にわたって、その位置は変化します。熱帯黄道帯と恒星黄道帯の開始点間の角度分離 (現在約 24 度) は、アヤナムシャとして知られています。`, ko: `이는 서양 시스템에서 "양자리"라고 불리는 황도대 부분이 특정 항성 별자리에 영구적으로 연결되어 있지 않다는 것을 의미합니다. 장기간에 걸쳐 위치가 변경됩니다. 열대 황도대와 항성 황도대의 시작점 사이의 각도 분리(현재 약 24도)를 아야남샤(Ayanamsha)라고 합니다.`,} },
      { type: "paragraph", text: { en: `Traditional Jyotish also employs the equal-house concept, where each house spans 30 degrees and corresponds directly with a sign in the Sidereal Zodiac. Western Astrology frequently uses unequal house division systems.`, hi: `पारंपरिक ज्योतिष भी समान-घर की अवधारणा को नियोजित करता है, जहां प्रत्येक घर 30 डिग्री तक फैला होता है और नाक्षत्र राशि चक्र में एक संकेत के साथ सीधे मेल खाता है। पश्चिमी ज्योतिष अक्सर असमान गृह विभाजन प्रणालियों का उपयोग करता है।`, ja: `伝統的なジョーティッシュでは、各ハウスが 30 度に広がり、恒星黄道帯のサインに直接対応するイコールハウスの概念も採用されています。西洋占星術では、不均等なハウス分割システムが頻繁に使用されます。`, ko: `전통적인 Jyotish는 또한 각 하우스가 30도에 걸쳐 있고 항성 황도대의 별자리와 직접적으로 일치하는 평등 하우스 개념을 사용합니다. 서양 점성술은 불평등한 하우스 분할 시스템을 자주 사용합니다.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish Uses ‘Functional Benefics’ and ‘Functional Malefics’`, hi: `ज्योतिष 'कार्यात्मक लाभ' और 'कार्यात्मक अशुभ' का उपयोग करता है`, ja: `ジョーティッシュは「機能的ベネフィックス」と「機能的マレフィックス」を使用します`, ko: `Jyotish는 '기능적 이점'과 '기능적 유해성'을 사용합니다.`,} },
      { type: "paragraph", text: { en: `Beyond their natural benefic or malefic tendencies, planets in Jyotish acquire additional characteristics based on the houses they own or rule within an individual's birth chart. Western Astrology has no direct equivalent to this concept.`, hi: `अपनी प्राकृतिक लाभकारी या अशुभ प्रवृत्तियों से परे, ज्योतिष में ग्रह किसी व्यक्ति की जन्म कुंडली में उनके स्वामित्व वाले या शासन करने वाले घरों के आधार पर अतिरिक्त विशेषताएं प्राप्त करते हैं। पश्चिमी ज्योतिष में इस अवधारणा का कोई सीधा समकक्ष नहीं है।`, ja: `ジョーティッシュの惑星は、生来の吉凶の傾向を超えて、個人の出生図内で所有または支配するハウスに基づいて追加の特徴を獲得します。西洋占星術には、この概念に直接相当するものはありません。`, ko: `자연적인 유익 또는 해로운 경향 외에도 Jyotish의 행성은 개인의 출생 차트 내에서 소유하거나 지배하는 주택을 기반으로 추가 특성을 얻습니다. 서양 점성술은 이 개념과 직접적으로 동등한 것이 없습니다.`,} },
      { type: "paragraph", text: { en: `For instance, Mars—naturally considered a malefic planet—can become an exceptionally positive influence for someone with a Leo (Sidereal) Ascendant. Conversely, Venus, generally regarded as a natural benefic, can become quite unfavorable for a person with a Pisces (Sidereal) Ascendant.`, hi: `उदाहरण के लिए, मंगल - जिसे स्वाभाविक रूप से एक अशुभ ग्रह माना जाता है - सिंह (नाक्षत्र) लग्न वाले किसी व्यक्ति के लिए असाधारण सकारात्मक प्रभाव बन सकता है। इसके विपरीत, शुक्र, जिसे आम तौर पर एक प्राकृतिक लाभकारी माना जाता है, मीन लग्न वाले व्यक्ति के लिए काफी प्रतिकूल हो सकता है।`, ja: `たとえば、火星は当然凶星と考えられていますが、獅子座（恒星）のアセンダントを持つ人にとって、非常にポジティブな影響を与える可能性があります。逆に、一般的に自然の恩恵を受けると考えられている金星は、魚座（恒星）のアセンダントを持つ人にとっては非常に不利になる可能性があります。`, ko: `예를 들어, 자연적으로 흉한 행성으로 간주되는 화성은 사자자리(항성) 승천자가 있는 사람에게 매우 긍정적인 영향을 미칠 수 있습니다. 반대로, 일반적으로 자연적인 이익으로 간주되는 금성은 물고기자리(항성) 승천자를 가진 사람에게는 상당히 불리해질 수 있습니다.`,} },
      { type: "paragraph", text: { en: `This principle is essential for accurate chart interpretation and for prescribing planetary remedies, including the recommendation of gemstones.`, hi: `यह सिद्धांत सटीक चार्ट व्याख्या और रत्नों की सिफारिश सहित ग्रहों के उपचार निर्धारित करने के लिए आवश्यक है।`, ja: `この原則は、チャートを正確に解釈し、宝石の推奨を含む惑星の治療法を処方するために不可欠です。`, ko: `이 원칙은 정확한 차트 해석과 보석 추천을 포함한 행성 치료법 처방에 필수적입니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "paragraph", text: { en: `[1] Jyotish addresses predictions relating to the four primary areas of life described in the Vedas: Artha, Dharma, Kama, and Moksha.`, hi: `[1] ज्योतिष वेदों में वर्णित जीवन के चार प्राथमिक क्षेत्रों: अर्थ, धर्म, काम और मोक्ष से संबंधित भविष्यवाणियों को संबोधित करता है।`, ja: `[1] ジョーティッシュは、ヴェーダに記述されている人生の 4 つの主要な領域、つまりアルタ、ダルマ、カーマ、モクシャに関する予測に取り組んでいます。`, ko: `[1] Jyotish는 Vedas에 설명된 삶의 네 가지 기본 영역인 Artha, Dharma, Kama 및 Moksha와 관련된 예측을 다룹니다.`,} },
      { type: "paragraph", text: { en: `• Artha relates to wealth in its broadest sense, including money, prosperity, children, knowledge, food, and health.`, hi: `• अर्थ अपने व्यापक अर्थों में धन से संबंधित है, जिसमें धन, समृद्धि, बच्चे, ज्ञान, भोजन और स्वास्थ्य शामिल हैं।`, ja: `• Artha は、お金、繁栄、子供、知識、食べ物、健康など、最も広い意味での富に関係します。`, ko: `• Artha는 돈, 번영, 자녀, 지식, 음식, 건강 등 가장 넓은 의미의 부와 관련이 있습니다.`,} },
      { type: "paragraph", text: { en: `• Dharma concerns duty, character, righteous action, and activities that support evolution and alignment with natural law, including career and life purpose.`, hi: `• धर्म कर्तव्य, चरित्र, धार्मिक कार्य और गतिविधियों से संबंधित है जो कैरियर और जीवन उद्देश्य सहित प्राकृतिक कानून के साथ विकास और संरेखण का समर्थन करते हैं।`, ja: `• ダルマは、義務、人格、正義の行動、キャリアや人生の目的など、進化と自然法との調和をサポートする活動に関係します。`, ko: `• 다르마는 직업과 삶의 목적을 포함하여 진화와 자연법에의 일치를 지원하는 의무, 성품, 의로운 행동 및 활동에 관한 것입니다.`,} },
      { type: "paragraph", text: { en: `• Kama refers to desire and therefore encompasses relationships, sensory pleasures, ambitions, and personal aspirations.`, hi: `• काम इच्छा को संदर्भित करता है और इसलिए रिश्तों, संवेदी सुखों, महत्वाकांक्षाओं और व्यक्तिगत आकांक्षाओं को शामिल करता है।`, ja: `• カーマは欲望を指し、したがって人間関係、感覚的な喜び、野心、個人的な願望を含みます。`, ko: `• 카마는 욕망을 의미하므로 관계, 감각적 즐거움, 야망 및 개인적 열망을 포함합니다.`,} },
      { type: "paragraph", text: { en: `• Moksha relates to spiritual growth, inner development, and progress toward Self-realization.`, hi: `• मोक्ष का संबंध आध्यात्मिक विकास, आंतरिक विकास और आत्म-प्राप्ति की दिशा में प्रगति से है।`, ja: `・モクシャは精神的な成長、内なる発展、自己実現に向けた進歩に関係します。`, ko: `• 목샤(Moksha)는 영적 성장, 내적 발전, 자아 실현을 향한 진보와 관련이 있습니다.`,} },
    ],
  },
  {
    id: "paradigm-shift",
    section: "introduction",
    title: { en: `Vedic Astrology – A Paradigm Shift`, hi: `वैदिक ज्योतिष - एक आदर्श परिवर्तन`, ja: `ヴェーダ占星術 – パラダイムシフト`, ko: `베다 점성술 - 패러다임 전환`,},
    related: ["western-differences","planetary-forces","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Vedic Astrology – A Paradigm Shift`, hi: `वैदिक ज्योतिष - एक आदर्श परिवर्तन`, ja: `ヴェーダ占星術 – パラダイムシフト`, ko: `베다 점성술 - 패러다임 전환`,} },
      { type: "paragraph", text: { en: `Summary: This article explores the paradigm shift required for Western Astrologers to understand the fundamental principles that underpin the predictive and preventive system of Vedic Astrology. These principles include concepts such as reincarnation, karma, planetary arrangements as coded information, the possibility of modifying returning karma, and the understanding that consciousness itself is the ultimate reality.`, hi: `सारांश: यह लेख पश्चिमी ज्योतिषियों के लिए वैदिक ज्योतिष की भविष्यवाणी और निवारक प्रणाली को रेखांकित करने वाले मूलभूत सिद्धांतों को समझने के लिए आवश्यक प्रतिमान बदलाव की पड़ताल करता है। इन सिद्धांतों में पुनर्जन्म, कर्म, कोडित जानकारी के रूप में ग्रहों की व्यवस्था, लौटने वाले कर्म को संशोधित करने की संभावना और यह समझ कि चेतना ही अंतिम वास्तविकता है, जैसी अवधारणाएं शामिल हैं।`, ja: `概要: この記事では、西洋占星術師がヴェーダ占星術の予測および予防システムを支える基本原則を理解するために必要なパラダイム シフトについて考察します。これらの原則には、輪廻転生、カルマ、コード化された情報としての惑星の配置、戻ってくるカルマを修正する可能性、意識そのものが究極の現実であるという理解などの概念が含まれます。`, ko: `요약: 이 기사는 서양 점성술사가 베다 점성술의 예측 및 예방 시스템을 뒷받침하는 기본 원리를 이해하는 데 필요한 패러다임 전환을 탐구합니다. 이러한 원칙에는 환생, 카르마, 암호화된 정보로서의 행성 배열, 되돌아오는 카르마의 수정 가능성, 의식 자체가 궁극적인 현실이라는 이해와 같은 개념이 포함됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish – A Major Paradigm Shift for Western Astrologers`, hi: `ज्योतिष - पश्चिमी ज्योतिषियों के लिए एक प्रमुख आदर्श बदलाव`, ja: `ジョーティッシュ – 西洋占星術家にとっての大きなパラダイムシフト`, ko: `Jyotish – 서양 점성술사를 위한 주요 패러다임 전환`,} },
      { type: "paragraph", text: { en: `A Self-realized Vedic Master and universal Guru once made the following profound statement regarding Vedic Astrology:`, hi: `एक स्वयंसिद्ध वैदिक गुरु और सार्वभौमिक गुरु ने एक बार वैदिक ज्योतिष के संबंध में निम्नलिखित गहन कथन दिया था:`, ja: `自己実現したヴェーダのマスターであり普遍的なグルは、かつてヴェーダ占星術に関して次のような深遠な発言をしました。`, ko: `스스로 깨달은 베다 스승이자 보편적인 구루는 베다 점성술에 관해 다음과 같은 심오한 진술을 한 적이 있습니다.`,} },
      { type: "paragraph", text: { en: `“The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It’s one Being, one consciousness, one Self, that manifests itself into this varied universe.” [1]`, hi: `"ज्योतिष का उद्देश्य आपको उस अंतिम सत्य तक ले जाना है कि संपूर्ण ब्रह्मांड एक जीव है। यह एक अस्तित्व, एक चेतना, एक स्व है, जो इस विविध ब्रह्मांड में प्रकट होता है।" [1]`, ja: `「占星術の目的は、宇宙全体が一つの有機体であるという究極の真実にあなたを導くことです。この多様な宇宙に現れるのは、一つの存在、一つの意識、一つの自己です。」 [1]`, ko: `"점성술의 목적은 우주 전체가 하나의 유기체라는 궁극적인 진실을 알려주는 것입니다. 이 다양한 우주에 나타나는 것은 하나의 존재, 하나의 의식, 하나의 자아입니다." [1]`,} },
      { type: "paragraph", text: { en: `Similar perspectives are shared by Masters from many spiritual traditions, including Buddhist, Taoist, Tantric, Yogic, and others. These views arise from direct experiential knowledge gained through higher states of consciousness.`, hi: `बौद्ध, ताओवादी, तांत्रिक, योगिक और अन्य सहित कई आध्यात्मिक परंपराओं के गुरुओं द्वारा समान दृष्टिकोण साझा किए जाते हैं। ये विचार चेतना की उच्च अवस्थाओं के माध्यम से प्राप्त प्रत्यक्ष अनुभवात्मक ज्ञान से उत्पन्न होते हैं।`, ja: `同様の視点は、仏教、道教、タントラ、ヨガなどを含む多くの精神的伝統のマスターたちも共有しています。これらの見解は、より高い意識状態を通じて得られた直接的な経験的知識から生じています。`, ko: `불교, 도교, 탄트라, 요가 등을 포함한 많은 영적 전통의 스승들도 비슷한 관점을 공유합니다. 이러한 견해는 더 높은 의식 상태를 통해 얻은 직접적인 경험적 지식에서 비롯됩니다.`,} },
      { type: "paragraph", text: { en: `It is worthwhile reflecting on the astrological implications of this statement. It suggests that the ultimate reality is not matter or energy, but consciousness itself. At its deepest level, Vedic Astrology therefore deals with a field of information that emerges from universal consciousness.`, hi: `इस कथन के ज्योतिषीय निहितार्थ पर विचार करना सार्थक है। यह सुझाव देता है कि अंतिम वास्तविकता पदार्थ या ऊर्जा नहीं है, बल्कि चेतना ही है। इसलिए, अपने सबसे गहरे स्तर पर, वैदिक ज्योतिष उस सूचना के क्षेत्र से संबंधित है जो सार्वभौमिक चेतना से उभरती है।`, ja: `この声明の占星術的な意味を熟考する価値はあります。それは、究極の現実は物質やエネルギーではなく、意識そのものであることを示唆しています。したがって、ヴェーダ占星術はその最も深いレベルで、普遍意識から現れる情報分野を扱います。`, ko: `이 진술이 갖는 점성학적 의미를 곰곰이 생각해 볼 가치가 있습니다. 이는 궁극적인 현실이 물질이나 에너지가 아니라 의식 자체임을 암시합니다. 따라서 베다 점성술은 가장 깊은 수준에서 보편적 의식에서 나오는 정보 분야를 다루고 있습니다.`,} },
      { type: "paragraph", text: { en: `To fully appreciate where Jyotish originates from, a significant shift in perspective is often required for astrologers who have been educated within Western astrological frameworks.`, hi: `ज्योतिष की उत्पत्ति कहां से हुई है, इसकी पूरी तरह से सराहना करने के लिए अक्सर उन ज्योतिषियों के लिए परिप्रेक्ष्य में एक महत्वपूर्ण बदलाव की आवश्यकता होती है, जिन्हें पश्चिमी ज्योतिषीय ढांचे के भीतर शिक्षित किया गया है।`, ja: `ジョーティッシュの起源を十分に理解するには、西洋占星術の枠組みの中で教育を受けた占星術師にとって、視点の大幅な変更が必要になることがよくあります。`, ko: `Jyotish가 어디에서 유래했는지 완전히 이해하려면 서양 점성술 체계 내에서 교육을 받은 점성가에게는 종종 관점의 상당한 변화가 필요합니다.`,} },
      { type: "heading", level: 3, text: { en: `Some Examples of Major Paradigm Shifts`, hi: `प्रमुख प्रतिमान बदलाव के कुछ उदाहरण`, ja: `大きなパラダイムシフトの例`, ko: `주요 패러다임 변화의 몇 가지 예`,} },
      { type: "paragraph", text: { en: `Below are a few examples of paradigm shifts that dramatically changed humanity’s understanding of reality. If you are already familiar with these examples, you may wish to proceed directly to the section: “Paradigm Changing Concepts in Jyotish Astrology.”`, hi: `नीचे प्रतिमान बदलावों के कुछ उदाहरण दिए गए हैं जिन्होंने वास्तविकता के बारे में मानवता की समझ को नाटकीय रूप से बदल दिया है। यदि आप पहले से ही इन उदाहरणों से परिचित हैं, तो आप सीधे अनुभाग पर आगे बढ़ना चाह सकते हैं: "ज्योतिष में प्रतिमान बदलने वाली अवधारणाएँ।"`, ja: `以下に、人類の現実認識を劇的に変えたパラダイムシフトの例をいくつか挙げます。これらの例をすでによく理解している場合は、「ジョーティッシュにおける概念を変えるパラダイム」のセクションに直接進んでください。`, ko: `다음은 현실에 대한 인류의 이해를 극적으로 변화시킨 패러다임 전환의 몇 가지 예입니다. 이러한 예에 이미 익숙하다면 "Jyotish 점성술의 패러다임 변화 개념" 섹션으로 직접 진행하고 싶을 수도 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Shift from ‘Flat-Earth’ to Heliocentric Viewpoint`, hi: `'सपाट-पृथ्वी' से हेलिओसेंट्रिक दृष्टिकोण में बदलाव`, ja: `「地球平面」から太陽中心の視点への移行`, ko: `'평평한 지구'에서 태양중심적 관점으로 전환`,} },
      { type: "paragraph", text: { en: `For centuries, humanity believed that the Sun and planets revolved around the Earth, and that the Earth itself occupied the centre of the universe. These ideas became deeply embedded within society and formed a conceptual framework that shaped the way people viewed reality. The scholars and institutions of the time, particularly the Church, strongly supported these beliefs.`, hi: `सदियों से, मानवता का मानना ​​था कि सूर्य और ग्रह पृथ्वी के चारों ओर घूमते हैं, और पृथ्वी स्वयं ब्रह्मांड के केंद्र में है। ये विचार समाज में गहराई से समाहित हो गए और एक वैचारिक ढाँचा तैयार किया जिसने लोगों के वास्तविकता को देखने के तरीके को आकार दिया। उस समय के विद्वानों और संस्थानों, विशेषकर चर्च ने, इन मान्यताओं का पुरजोर समर्थन किया।`, ja: `何世紀にもわたって、人類は太陽と惑星が地球の周りを回っており、地球自体が宇宙の中心を占めていると信じていました。これらの考えは社会に深く埋め込まれ、人々の現実の見方を形作る概念的な枠組みを形成しました。当時の学者や機関、特に教会はこれらの信念を強く支持しました。`, ko: `수세기 동안 인류는 태양과 행성이 지구를 중심으로 회전하며 지구 자체가 우주의 중심을 차지하고 있다고 믿었습니다. 이러한 아이디어는 사회에 깊이 뿌리 박혀 사람들이 현실을 보는 방식을 형성하는 개념적 틀을 형성했습니다. 당시의 학자와 기관, 특히 교회는 이러한 믿음을 강력하게 지지했습니다.`,} },
      { type: "paragraph", text: { en: `Eventually, overwhelming scientific evidence emerged showing that what had once been regarded as self-evident truth was simply the result of an Earth-centred perspective. Contrary to appearances, the Earth and planets revolve around the Sun.`, hi: `आख़िरकार, जबरदस्त वैज्ञानिक सबूत सामने आए जो दिखाते हैं कि जिसे कभी स्व-स्पष्ट सत्य माना जाता था वह केवल पृथ्वी-केंद्रित परिप्रेक्ष्य का परिणाम था। दिखावे के विपरीत, पृथ्वी और ग्रह सूर्य के चारों ओर घूमते हैं।`, ja: `最終的に、かつては自明の真実と考えられていたものが単に地球中心の視点の結果であることを示す圧倒的な科学的証拠が現れました。見た目に反して、地球や惑星は太陽の周りを回っています。`, ko: `결국, 한때 자명한 진실로 여겨졌던 것이 단순히 지구 중심적 관점의 결과였음을 보여주는 압도적인 과학적 증거가 등장했습니다. 겉보기와는 달리 지구와 행성은 태양을 중심으로 회전합니다.`,} },
      { type: "paragraph", text: { en: `Looking back today, it can be difficult to appreciate the upheaval caused by this change in understanding, or why supporters of the new viewpoint were labelled heretics. It is equally difficult to understand why the old ideas persisted for so long. This serves as one example of a major paradigm shift. There are many others.`, hi: `आज पीछे मुड़कर देखें, तो समझ में इस बदलाव के कारण हुई उथल-पुथल की सराहना करना मुश्किल हो सकता है, या नए दृष्टिकोण के समर्थकों को विधर्मी क्यों करार दिया गया। यह समझना भी उतना ही कठिन है कि पुराने विचार इतने लंबे समय तक क्यों कायम रहे। यह एक प्रमुख प्रतिमान बदलाव का एक उदाहरण है। और भी बहुत सारे हैं.`, ja: `今日振り返ってみると、この理解の変化によって引き起こされた大混乱や、なぜ新しい視点の支持者が異端者のレッテルを貼られたのかを理解するのは難しいかもしれません。なぜ古い考えがこれほど長い間存続し続けたのかを理解することも同様に困難です。これは大きなパラダイムシフトの一例です。他にもたくさんあります。`, ko: `오늘날을 돌이켜보면, 이러한 이해의 변화로 인한 격변을 이해하기 어려울 수 있으며, 왜 새로운 관점을 지지하는 사람들이 이단자로 분류되었는지 이해하기 어려울 수 있습니다. 오래된 생각이 왜 그렇게 오랫동안 지속되었는지 이해하는 것도 똑같이 어렵습니다. 이는 주요 패러다임 전환의 한 예입니다. 다른 많은 것들이 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Shift from ‘Created’ to ‘Evolved’ Viewpoint`, hi: `'निर्मित' से 'विकसित' दृष्टिकोण में बदलाव`, ja: `「創造」から「進化」への視点の転換`, ko: `'만들어진' 관점에서 '진화한' 관점으로 전환`,} },
      { type: "paragraph", text: { en: `More recently, the concept of biological evolution challenged the long-established belief that God created all life forms exactly as they exist today and that no change was possible within the divine plan.`, hi: `हाल ही में, जैविक विकास की अवधारणा ने लंबे समय से स्थापित धारणा को चुनौती दी कि भगवान ने सभी जीवन रूपों को बिल्कुल वैसे ही बनाया जैसे वे आज मौजूद हैं और दिव्य योजना के भीतर कोई बदलाव संभव नहीं है।`, ja: `つい最近、生物進化の概念は、神がすべての生命体を今日存在するとおりに創造し、神の計画内でいかなる変更も不可能であるという長年確立された信念に疑問を投げかけました。`, ko: `최근에는 생물학적 진화라는 개념이 하나님께서 모든 생명체를 오늘날 존재하는 그대로 창조하셨으며 하나님의 계획 내에서는 어떤 변화도 불가능하다는 오랜 믿음에 도전했습니다.`,} },
      { type: "paragraph", text: { en: `What began as a theory eventually became accepted fact when scientific methods enabled the dating of fossils, many of which were found to be hundreds of millions or even billions of years old. Although some religious fundamentalists continue to believe that everything was created only a few thousand years ago, evolutionary theory fundamentally transformed our understanding of life on Earth.`, hi: `जो एक सिद्धांत के रूप में शुरू हुआ वह अंततः स्वीकृत तथ्य बन गया जब वैज्ञानिक तरीकों ने जीवाश्मों की डेटिंग को सक्षम किया, जिनमें से कई सैकड़ों लाखों या अरबों वर्ष पुराने पाए गए। हालाँकि कुछ धार्मिक कट्टरपंथियों का मानना ​​है कि सब कुछ केवल कुछ हज़ार साल पहले ही बनाया गया था, विकासवादी सिद्धांत ने पृथ्वी पर जीवन के बारे में हमारी समझ को मौलिक रूप से बदल दिया।`, ja: `理論として始まったものは、科学的手法によって化石の年代測定が可能になり、その多くが数億年、さらには数十億年前のものであることが判明したとき、最終的に受け入れられた事実になりました。一部の宗教原理主義者は、すべてはわずか数千年前に創造されたと信じ続けていますが、進化論は地球上の生命に対する私たちの理解を根本的に変えました。`, ko: `이론으로 시작된 것이 과학적 방법으로 화석의 연대 측정이 가능해지면서 결국 사실로 받아들여지게 되었습니다. 그 중 다수는 수억 년, 심지어 수십억 년 된 것으로 밝혀졌습니다. 일부 종교적 근본주의자들은 모든 것이 단지 수천 년 전에 창조되었다고 계속 믿고 있지만, 진화론은 지구상의 생명체에 대한 우리의 이해를 근본적으로 변화시켰습니다.`,} },
      { type: "heading", level: 3, text: { en: `Shift from Newtonian Mechanistic to Quantum Understandings`, hi: `न्यूटोनियन मैकेनिस्टिक से क्वांटम समझ की ओर बदलाव`, ja: `ニュートン力学から量子理解への移行`, ko: `뉴턴 역학에서 양자 이해로 전환`,} },
      { type: "paragraph", text: { en: `Another major paradigm shift occurred in physics. The laws of motion developed by Isaac Newton proved insufficient to explain all observed phenomena, particularly those involving subatomic particles or objects travelling near the speed of light.`, hi: `भौतिकी में एक और बड़ा बदलाव आया। आइज़ैक न्यूटन द्वारा विकसित गति के नियम सभी देखी गई घटनाओं को समझाने के लिए अपर्याप्त साबित हुए, विशेष रूप से उप-परमाणु कणों या प्रकाश की गति के करीब यात्रा करने वाली वस्तुओं से संबंधित।`, ja: `もう一つの大きなパラダイムシフトが物理学で起こりました。アイザック・ニュートンによって開発された運動法則は、観察されたすべての現象、特に光速に近い速度で移動する素粒子や物体に関係する現象を説明するには不十分であることが判明しました。`, ko: `물리학에서는 또 다른 주요 패러다임 변화가 일어났습니다. 아이작 뉴턴이 개발한 운동 법칙은 관찰된 모든 현상, 특히 아원자 입자나 빛의 속도에 가깝게 움직이는 물체와 관련된 현상을 설명하기에는 불충분하다는 것이 입증되었습니다.`,} },
      { type: "paragraph", text: { en: `This led to the development of Einstein’s theory of relativity and the emergence of quantum physics. As with all major shifts in understanding, acceptance was gradual. Significant changes in worldview often require time before they become widely integrated into public consciousness. As the saying goes, “Paradigm shifts usually occur one funeral at a time.”`, hi: `इससे आइंस्टीन के सापेक्षता के सिद्धांत का विकास हुआ और क्वांटम भौतिकी का उदय हुआ। समझ में सभी प्रमुख बदलावों की तरह, स्वीकृति धीरे-धीरे हुई। विश्वदृष्टि में महत्वपूर्ण परिवर्तनों को सार्वजनिक चेतना में व्यापक रूप से एकीकृत होने से पहले अक्सर समय की आवश्यकता होती है। जैसा कि कहा जाता है, "प्रतिमान परिवर्तन आम तौर पर एक समय में एक अंतिम संस्कार में होता है।"`, ja: `これがアインシュタインの相対性理論の発展と量子物理学の出現につながりました。すべての大きな理解の変化と同様、受け入れは徐々に進みました。世界観の大きな変化は、多くの場合、それが一般の意識に広く統合されるまでに時間がかかります。ことわざにあるように、「パラダイムシフトは通常、葬儀ごとに起こります。」`, ko: `이는 아인슈타인의 상대성이론의 발전과 양자물리학의 출현으로 이어졌다. 이해의 모든 주요 변화와 마찬가지로 수용도 점진적이었습니다. 세계관의 중요한 변화가 대중의 의식에 널리 통합되기까지는 시간이 필요한 경우가 많습니다. 속담처럼, “패러다임 전환은 대개 한 번에 한 장례식씩 발생합니다.”`,} },
      { type: "heading", level: 3, text: { en: `Paradigm Changing Concepts in Jyotish Astrology`, hi: `ज्योतिष में प्रतिमान बदलती अवधारणाएँ`, ja: `ジョーティッシュの概念を変えるパラダイム`, ko: `Jyotish 점성술의 패러다임 변화 개념`,} },
      { type: "heading", level: 3, text: { en: `1. Planets Do Not Affect People`, hi: `1. ग्रह लोगों को प्रभावित नहीं करते`, ja: `1. 惑星は人々に影響を与えない`, ko: `1. 행성은 사람에게 영향을 미치지 않습니다`,} },
      { type: "paragraph", text: { en: `A Jyotish Astrologer understands that planets do not affect people—it is people who affect people.`, hi: `एक ज्योतिषी समझता है कि ग्रह लोगों को प्रभावित नहीं करते हैं - बल्कि लोग ही लोगों को प्रभावित करते हैं।`, ja: `ジョーティッシュ師は、惑星が人に影響を与えるのではなく、人に影響を与えるのは人であることを理解しています。`, ko: `Jyotish 점성가는 행성이 사람에게 영향을 미치는 것이 아니라 사람이 사람에게 영향을 미친다는 것을 이해합니다.`,} },
      { type: "paragraph", text: { en: `Within Western Astrology, it is easy to adopt what might be called an "astrological victim consciousness." For example, someone may say: “I’m going through a difficult period because of my Saturn transit.” This implies that Saturn is somehow responsible for the hardships being experienced.`, hi: `पश्चिमी ज्योतिष में, जिसे "ज्योतिषीय पीड़ित चेतना" कहा जा सकता है, उसे अपनाना आसान है। उदाहरण के लिए, कोई कह सकता है: "मैं अपने शनि पारगमन के कारण कठिन दौर से गुज़र रहा हूँ।" इसका तात्पर्य यह है कि अनुभव की जा रही कठिनाइयों के लिए शनि किसी तरह जिम्मेदार है।`, ja: `西洋占星術では、いわゆる「占星​​術的被害者意識」が入りやすいです。たとえば、「土星の通過のせいで、私は困難な時期を経験している」と言う人がいるかもしれません。これは、土星が経験している困難に何らかの責任があることを意味します。`, ko: `서양 점성술에서는 "점성학적 희생의식"이라고 불리는 것을 채택하기가 쉽습니다. 예를 들어, 누군가가 “나는 토성 통과 때문에 힘든 시기를 보내고 있어요.”라고 말할 수 있습니다. 이것은 토성이 겪고 있는 어려움에 어느 정도 책임이 있음을 의미합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish rejects this idea. It teaches that any condition or circumstance we experience is the result of our own past thoughts, words, and actions.`, hi: `ज्योतिष इस विचार को ख़ारिज करता है। यह सिखाता है कि हम जिस भी स्थिति या परिस्थिति का अनुभव करते हैं वह हमारे अपने पिछले विचारों, शब्दों और कार्यों का परिणाम है।`, ja: `ジョーティッシュはこの考えを拒否します。私たちが経験するあらゆる状態や状況は、私たち自身の過去の思考、言葉、行動の結果であると教えています。`, ko: `Jyotish는 이 아이디어를 거부합니다. 우리가 경험하는 모든 조건이나 상황은 우리 자신의 과거 생각, 말, 행동의 결과임을 가르칩니다.`,} },
      { type: "paragraph", text: { en: `A common response might be: “I cannot remember doing anything that would produce what I am currently experiencing.”`, hi: `एक सामान्य प्रतिक्रिया यह हो सकती है: "मुझे ऐसा कुछ भी करना याद नहीं है जिससे वह परिणाम मिले जो मैं वर्तमान में अनुभव कर रहा हूँ।"`, ja: `一般的な反応は次のようなものかもしれません。「私が現在経験していることを生み出すようなことを何もした覚えがありません。」`, ko: `일반적인 반응은 다음과 같습니다. “나는 현재 경험하고 있는 것과 같은 일을 한 적이 전혀 기억나지 않습니다.”`,} },
      { type: "paragraph", text: { en: `From the Jyotish perspective, the answer is straightforward. Our memory simply does not extend far enough back. To fully understand our present circumstances, we may need access to memories stretching across many lifetimes.`, hi: `ज्योतिष के दृष्टिकोण से, उत्तर सीधा है। हमारी याददाश्त बहुत पीछे तक नहीं जाती। अपनी वर्तमान परिस्थितियों को पूरी तरह से समझने के लिए, हमें कई जन्मों तक फैली यादों तक पहुंच की आवश्यकता हो सकती है।`, ja: `ジョーティッシュの観点からすれば、答えは簡単です。私たちの記憶は十分に遡ることができません。私たちの現在の状況を完全に理解するには、多くの生涯にわたる記憶にアクセスする必要があるかもしれません。`, ko: `Jyotish의 관점에서 보면 대답은 간단합니다. 우리의 기억은 충분히 뒤로 확장되지 않습니다. 현재 상황을 완전히 이해하려면 여러 생애에 걸친 기억에 접근해야 할 수도 있습니다.`,} },
      { type: "paragraph", text: { en: `For this reason, Jyotish incorporates the principles of reincarnation and karma—the return of the fruits of past actions.`, hi: `इस कारण से, ज्योतिष पुनर्जन्म और कर्म के सिद्धांतों को शामिल करता है - पिछले कर्मों के फल की वापसी।`, ja: `このため、ジョーティッシュには輪廻転生とカルマ、つまり過去の行為の結果が戻ってくるという原則が組み込まれています。`, ko: `이러한 이유로 Jyotish는 환생과 카르마, 즉 과거 행위의 결과를 되돌리는 원리를 통합합니다.`,} },
      { type: "paragraph", text: { en: `At its most fundamental level, the mechanics of Jyotish rely upon the Vedic Model of Reality, which views the universe and all beings within it as parts of one interconnected whole.`, hi: `अपने सबसे बुनियादी स्तर पर, ज्योतिष की यांत्रिकी वास्तविकता के वैदिक मॉडल पर निर्भर करती है, जो ब्रह्मांड और उसके भीतर के सभी प्राणियों को एक दूसरे से जुड़े पूरे हिस्से के रूप में देखता है।`, ja: `最も基本的なレベルでは、ジョーティッシュの仕組みは、宇宙とその中のすべての存在を、相互に接続された 1 つの全体の一部として見る、現実のヴェーダ モデルに依存しています。`, ko: `가장 근본적인 수준에서 Jyotish의 메커니즘은 우주와 그 안에 있는 모든 존재를 하나의 상호 연결된 전체의 일부로 보는 베다 현실 모델에 의존합니다.`,} },
      { type: "heading", level: 3, text: { en: `2. We Were Not Born at a Particular Time Merely by Chance`, hi: `2. हमारा जन्म किसी विशेष समय पर मात्र संयोग से नहीं हुआ`, ja: `2. 私たちはたまたま特定の時期に生まれたわけではありません`, ko: `2. 우리는 단지 우연히 특정 시기에 태어난 것이 아니다`,} },
      { type: "paragraph", text: { en: `According to Jyotish, we were not born at a specific moment with a particular planetary arrangement merely by accident.`, hi: `ज्योतिष के अनुसार, हमारा जन्म किसी विशेष ग्रहीय व्यवस्था के साथ किसी विशेष क्षण में मात्र संयोगवश नहीं हुआ है।`, ja: `ジョーティッシュによれば、私たちは単に偶然に、特定の瞬間に特定の惑星配置で生まれたわけではありません。`, ko: `Jyotish에 따르면, 우리는 단지 우연히 특정 순간에 특정 행성 배열을 가지고 태어난 것이 아닙니다.`,} },
      { type: "paragraph", text: { en: `The Vedic tradition does not subscribe to the idea that the Creator plays dice. It would seem inherently unfair if some individuals were born into wealthy families while others entered lives of extreme hardship purely through chance.`, hi: `वैदिक परंपरा इस विचार से सहमत नहीं है कि निर्माता पासा खेलता है। यह स्वाभाविक रूप से अनुचित प्रतीत होगा यदि कुछ व्यक्तियों का जन्म धनी परिवारों में हुआ हो, जबकि अन्य लोग संयोग से अत्यधिक कठिनाई के जीवन में प्रवेश करते हों।`, ja: `ヴェーダの伝統は、創造主がサイコロを振るという考えを支持していません。もしある人が裕福な家庭に生まれ、他の人が全くの偶然で極度の困難な人生に出会ったとしたら、それは本質的に不公平であるように思われるでしょう。`, ko: `베다 전통은 창조주가 주사위 놀이를 한다는 생각을 따르지 않습니다. 어떤 개인은 부유한 가정에서 태어났지만 다른 개인은 순전히 우연을 통해 극심한 고난의 삶을 살았다면 그것은 본질적으로 불공평해 보일 것입니다.`,} },
      { type: "paragraph", text: { en: `Jyotish suggests that our birth time and place are determined by our past karmas and latent impressions, known as samskaras.`, hi: `ज्योतिष सुझाव देता है कि हमारा जन्म समय और स्थान हमारे पिछले कर्मों और अव्यक्त संस्कारों द्वारा निर्धारित होता है, जिन्हें संस्कार के रूप में जाना जाता है।`, ja: `ジョーティッシュは、私たちの出生時間と出生場所は、サムスカーラとして知られる過去のカルマと潜在的な印象によって決定されると示唆しています。`, ko: `Jyotish는 우리의 탄생 시간과 장소가 과거 카르마와 삼스카라(samskaras)로 알려진 잠재 인상에 의해 결정된다고 제안합니다.`,} },
      { type: "paragraph", text: { en: `The arrangement of the nine planets, together with their future transits through the twelve houses and twenty-seven Nakshatras, reflects how our life will unfold as a consequence of past actions. The moment of incarnation therefore mirrors the karmic lessons required for our evolution.`, hi: `नौ ग्रहों की व्यवस्था, बारह घरों और सत्ताईस नक्षत्रों के माध्यम से उनके भविष्य के पारगमन के साथ, यह दर्शाती है कि पिछले कार्यों के परिणामस्वरूप हमारा जीवन कैसे विकसित होगा। इसलिए अवतार का क्षण हमारे विकास के लिए आवश्यक कर्म सबक को प्रतिबिंबित करता है।`, ja: `9 つの惑星の配置は、12 ハウスと 27 のナクシャトラを通る将来の通過とともに、過去の行動の結果として私たちの人生がどのように展開するかを反映しています。したがって、受肉の瞬間は、私たちの進化に必要なカルマの教訓を反映しています。`, ko: `9개 행성의 배열은 12개의 하우스와 27개의 나크샤트라를 통과하는 미래의 이동과 함께 과거 행동의 결과로 우리 삶이 어떻게 전개될 것인지를 반영합니다. 그러므로 화신의 순간은 우리의 진화에 필요한 카르마 교훈을 반영합니다.`,} },
      { type: "paragraph", text: { en: `Through this celestial blueprint, Jyotish can identify both the benefits and challenges likely to arise, as well as the timing of their manifestation.`, hi: `इस खगोलीय ब्लूप्रिंट के माध्यम से, ज्योतिष संभावित लाभों और चुनौतियों, साथ ही उनके प्रकट होने के समय दोनों की पहचान कर सकता है।`, ja: `この天の青写真を通じて、ジョーティッシュは、今後発生する可能性のある利点と課題、およびそれらが現れるタイミングの両方を特定できます。`, ko: `이 천체 청사진을 통해 Jyotish는 발생할 수 있는 이점과 과제는 물론 그 출현 시기도 식별할 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `3. Planets Don’t Emit a Physical ‘Force’ that Affects People`, hi: `3. ग्रह किसी भौतिक 'बल' का उत्सर्जन नहीं करते जो लोगों को प्रभावित करता हो`, ja: `3. 惑星は人々に影響を与える物理的な「力」を発しない`, ko: `3. 행성은 사람에게 영향을 미치는 물리적인 '힘'을 방출하지 않습니다.`,} },
      { type: "paragraph", text: { en: `Many Western Astrologers believe that planets emit some form of force that influences human life, even though science has not yet identified such a force.`, hi: `कई पश्चिमी ज्योतिषियों का मानना ​​है कि ग्रह किसी प्रकार की शक्ति उत्सर्जित करते हैं जो मानव जीवन को प्रभावित करती है, हालांकि विज्ञान ने अभी तक ऐसी शक्ति की पहचान नहीं की है।`, ja: `多くの西洋占星術師は、科学はまだそのような力を特定していませんが、惑星は人間の生活に影響を与える何らかの形の力を発していると信じています。`, ko: `많은 서양 점성가들은 과학이 아직 그러한 힘을 확인하지 못했지만 행성이 인간의 삶에 영향을 미치는 어떤 형태의 힘을 방출한다고 믿습니다.`,} },
      { type: "paragraph", text: { en: `This concept is essentially mechanistic and rooted in a Newtonian model of reality.`, hi: `यह अवधारणा मूलतः यंत्रवत है और वास्तविकता के न्यूटोनियन मॉडल में निहित है।`, ja: `この概念は本質的に機械論的であり、現実のニュートンモデルに根ざしています。`, ko: `이 개념은 본질적으로 기계론적이며 뉴턴의 현실 모델에 뿌리를 두고 있습니다.`,} },
      { type: "paragraph", text: { en: `Vedic Astrology takes a different view. It sees planetary arrangements as information rather than physical or hidden esoteric forces. The positions of the planets at birth form a code that can be interpreted by a skilled Jyotish Astrologer and translated into meaningful predictions.`, hi: `वैदिक ज्योतिष एक अलग दृष्टिकोण रखता है। यह ग्रहों की व्यवस्था को भौतिक या छिपी हुई गूढ़ शक्तियों के बजाय सूचना के रूप में देखता है। जन्म के समय ग्रहों की स्थिति एक कोड बनाती है जिसकी व्याख्या एक कुशल ज्योतिषी द्वारा की जा सकती है और सार्थक भविष्यवाणियों में अनुवाद किया जा सकता है।`, ja: `ヴェーダ占星術は異なる見方をします。それは惑星の配置を物理的または隠された難解な力ではなく、情報として見ています。出生時の惑星の位置は、熟練したジョーティッシュ師によって解釈され、意味のある予測に変換されるコードを形成します。`, ko: `베다 점성술은 다른 견해를 취합니다. 행성 배열을 물리적이거나 숨겨진 난해한 힘이 아닌 정보로 간주합니다. 출생 시 행성의 위치는 숙련된 Jyotish 점성가가 해석하고 의미 있는 예측으로 번역할 수 있는 코드를 형성합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish also makes extensive use of Rahu and Ketu, the Moon’s nodes. These are not physical objects at all. They are mathematical points created where the Moon’s orbit intersects the ecliptic.`, hi: `ज्योतिष, चंद्रमा के नोड्स, राहु और केतु का भी व्यापक उपयोग करता है। ये बिल्कुल भी भौतिक वस्तुएं नहीं हैं। वे गणितीय बिंदु बनाए गए हैं जहां चंद्रमा की कक्षा क्रांतिवृत्त को काटती है।`, ja: `ジョーティッシュはまた、月のノードであるラーフとケートゥを広範囲に利用します。これらは決して物理的な物体ではありません。これらは、月の軌道が黄道と交差する場所に作成される数学的な点です。`, ko: `Jyotish는 또한 달의 노드인 Rahu와 Ketu를 광범위하게 사용합니다. 이것들은 전혀 물리적인 물체가 아닙니다. 이는 달의 궤도가 황도와 교차하는 곳에 생성된 수학적 지점입니다.`,} },
      { type: "paragraph", text: { en: `Since Rahu and Ketu have no material existence, they clearly cannot exert a physical force. Yet they are associated with powerful karmic effects and significant life events.`, hi: `चूँकि राहु और केतु का कोई भौतिक अस्तित्व नहीं है, इसलिए वे स्पष्ट रूप से कोई भौतिक बल नहीं लगा सकते। फिर भी वे शक्तिशाली कार्मिक प्रभावों और महत्वपूर्ण जीवन की घटनाओं से जुड़े हुए हैं।`, ja: `ラーフとケートゥには物質的な存在がないので、明らかに物理的な力を行使することができません。しかし、それらは強力なカルマ効果や重要な人生の出来事と関連しています。`, ko: `라후와 케투는 물질적 존재가 없기 때문에 분명히 물리적인 힘을 발휘할 수 없습니다. 그러나 그것들은 강력한 카르마 효과 및 중요한 삶의 사건과 연관되어 있습니다.`,} },
      { type: "paragraph", text: { en: `Further support for this information-based model comes from the fact that planetary effects vary dramatically according to an individual's Ascendant.[2] There is no direct equivalent of this concept in Western Astrology.`, hi: `इस सूचना-आधारित मॉडल के लिए और अधिक समर्थन इस तथ्य से मिलता है कि किसी व्यक्ति के लग्न के अनुसार ग्रहों का प्रभाव नाटकीय रूप से भिन्न होता है।[2] पश्चिमी ज्योतिष में इस अवधारणा का कोई प्रत्यक्ष समकक्ष नहीं है।`, ja: `この情報ベースのモデルのさらなる裏付けは、惑星の影響が個人のアセンダントに応じて劇的に変化するという事実から来ています。西洋占星術には、この概念に直接相当するものはありません。`, ko: `이 정보 기반 모델에 대한 추가 지원은 행성 효과가 개인의 어센던트에 따라 극적으로 다르다는 사실에서 비롯됩니다.[2] 서양 점성술에는 이 개념과 직접적으로 동등한 것이 없습니다.`,} },
      { type: "heading", level: 3, text: { en: `4. Jyotish Has No Need to Use Neptune, Uranus, Pluto or Asteroids`, hi: `4. ज्योतिष को नेपच्यून, यूरेनस, प्लूटो या क्षुद्रग्रहों का उपयोग करने की कोई आवश्यकता नहीं है`, ja: `4.ジョーティッシュは海王星、天王星、冥王星、小惑星を使う必要がない`, ko: `4. Jyotish는 해왕성, 천왕성, 명왕성 또는 소행성을 사용할 필요가 없습니다.`,} },
      { type: "paragraph", text: { en: `Many Western Astrologers assume that Jyotish is limited because it does not incorporate Neptune, Uranus, Pluto, or asteroids into its calculations.`, hi: `कई पश्चिमी ज्योतिषी मानते हैं कि ज्योतिष सीमित है क्योंकि यह अपनी गणना में नेप्च्यून, यूरेनस, प्लूटो या क्षुद्रग्रहों को शामिल नहीं करता है।`, ja: `多くの西洋占星術師は、ジョーティッシュは海王星、天王星、冥王星、小惑星を計算に組み込んでいないため、限界があると考えています。`, ko: `많은 서양 점성가들은 Jyotish가 계산에 해왕성, 천왕성, 명왕성 또는 소행성을 포함하지 않기 때문에 제한적이라고 가정합니다.`,} },
      { type: "paragraph", text: { en: `However, Jyotish does not regard this as a limitation.`, hi: `हालाँकि, ज्योतिष इसे कोई सीमा नहीं मानता।`, ja: `しかし、ジョーティッシュはこれを制限とは考えていません。`, ko: `그러나 Jyotish는 이를 제한 사항으로 간주하지 않습니다.`,} },
      { type: "paragraph", text: { en: `The positions of the seven visible planets, together with the Moon’s two nodes, across the twelve signs, twelve houses, and twenty-seven Nakshatras already provide a highly sophisticated system of encoded information.`, hi: `बारह राशियों, बारह घरों और सत्ताईस नक्षत्रों में चंद्रमा के दो नोड्स सहित सात दृश्यमान ग्रहों की स्थिति पहले से ही एन्कोडेड जानकारी की एक अत्यधिक परिष्कृत प्रणाली प्रदान करती है।`, ja: `12 のサイン、12 ハウス、27 のナクシャトラにわたる、目に見える 7 つの惑星の位置と月の 2 つのノードは、すでに高度に洗練された暗号化情報システムを提供しています。`, ko: `12개의 별자리, 12개의 집, 27개의 나크샤트라에 걸쳐 달의 두 노드와 함께 눈에 보이는 7개의 행성의 위치는 이미 암호화된 정보의 매우 정교한 시스템을 제공합니다.`,} },
      { type: "paragraph", text: { en: `Combined with transit analysis, this arrangement contains all the information necessary to understand the key areas of life: Artha, Dharma, Kama, and Moksha.[3]`, hi: `पारगमन विश्लेषण के साथ, इस व्यवस्था में जीवन के प्रमुख क्षेत्रों: अर्थ, धर्म, काम और मोक्ष को समझने के लिए आवश्यक सभी जानकारी शामिल है।[3]`, ja: `トランジット分析と組み合わせたこの構成には、人生の主要な領域であるアルタ、ダルマ、カーマ、モクシャを理解するために必要なすべての情報が含まれています[3]。`, ko: `대중교통 분석과 결합된 이 배열에는 삶의 주요 영역인 Artha, Dharma, Kama 및 Moksha를 이해하는 데 필요한 모든 정보가 포함되어 있습니다.[3]`,} },
      { type: "paragraph", text: { en: `Jyotish also uses the Moon’s position to determine major life periods known as Mahadashas, through which karmic results are delivered by the nine planets.`, hi: `ज्योतिष प्रमुख जीवन काल को निर्धारित करने के लिए चंद्रमा की स्थिति का भी उपयोग करता है जिसे महादशा के रूप में जाना जाता है, जिसके माध्यम से नौ ग्रहों द्वारा कर्म परिणाम दिए जाते हैं।`, ja: `ジョーティッシュはまた、月の位置を使用して、マハダシャーとして知られる主要な人生の期間を決定します。マハダシャーを通じて、9 つの惑星によってカルマの結果がもたらされます。`, ko: `Jyotish는 또한 달의 위치를 ​​사용하여 Mahadashas로 알려진 주요 수명 기간을 결정하며 이를 통해 9개의 행성에 의해 카르마 결과가 전달됩니다.`,} },
      { type: "paragraph", text: { en: `As a result, there is no requirement to include Neptune, Uranus, Pluto, or asteroids in order to make accurate and meaningful predictions.`, hi: `परिणामस्वरूप, सटीक और सार्थक भविष्यवाणियाँ करने के लिए नेपच्यून, यूरेनस, प्लूटो या क्षुद्रग्रहों को शामिल करने की कोई आवश्यकता नहीं है।`, ja: `その結果、正確で意味のある予測を行うために、海王星、天王星、冥王星、または小惑星を含める必要はありません。`, ko: `결과적으로 정확하고 의미 있는 예측을 하기 위해 해왕성, 천왕성, 명왕성 또는 소행성을 포함할 필요가 없습니다.`,} },
      { type: "heading", level: 3, text: { en: `5. Jyotish Provides Remedial Measures to Modify Returning Karmas`, hi: `5. ज्योतिष रिटर्निंग कर्मों को संशोधित करने के लिए उपचारात्मक उपाय प्रदान करता है`, ja: `5. ジョーティッシュは、戻ってくるカルマを修正するための是正措置を提供します`, ko: `5. Jyotish는 반환된 카르마를 수정하기 위한 교정 조치를 제공합니다.`,} },
      { type: "paragraph", text: { en: `Since all beings are viewed as part of an interconnected whole, participation in certain Vedic practices can influence returning karmas.`, hi: `चूंकि सभी प्राणियों को एक दूसरे से जुड़े संपूर्ण हिस्से के रूप में देखा जाता है, इसलिए कुछ वैदिक प्रथाओं में भागीदारी रिटर्निंग कर्मों को प्रभावित कर सकती है।`, ja: `すべての存在は相互に接続された全体の一部として見なされているため、特定のヴェーダ実践への参加は、戻ってくるカルマに影響を与える可能性があります。`, ko: `모든 존재는 상호 연결된 전체의 일부로 간주되기 때문에 특정 베다 관행에 참여하면 카르마가 되돌아오는 데 영향을 미칠 수 있습니다.`,} },
      { type: "paragraph", text: { en: `These may include prescribed acts of charity, specific Vedic ceremonies, the recitation of Sanskrit mantras, or the wearing of appropriate gemstones.`, hi: `इनमें दान के निर्धारित कार्य, विशिष्ट वैदिक समारोह, संस्कृत मंत्रों का पाठ, या उपयुक्त रत्न पहनना शामिल हो सकते हैं।`, ja: `これらには、所定の慈善行為、特定のヴェーダ儀式、サンスクリット語のマントラの暗唱、または適切な宝石の着用が含まれる場合があります。`, ko: `여기에는 규정된 자선 행위, 특정 베다 의식, 산스크리트어 만트라 낭송, 적절한 보석 착용 등이 포함될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Such methods are commonly referred to as Planetary Antidotes or Remedial Measures.`, hi: `ऐसी विधियों को आमतौर पर ग्रहीय मारक या उपचारात्मक उपाय कहा जाता है।`, ja: `このような方法は一般に、惑星への対処法または改善法と呼ばれます。`, ko: `이러한 방법을 일반적으로 행성 해독제 또는 치료 조치라고 합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish therefore offers the ability not only to identify returning karmas, but also to reduce, modify, or redirect their effects.[4]`, hi: `इसलिए ज्योतिष न केवल लौटने वाले कर्मों की पहचान करने की क्षमता प्रदान करता है, बल्कि उनके प्रभावों को कम करने, संशोधित करने या पुनर्निर्देशित करने की भी क्षमता प्रदान करता है।[4]`, ja: `したがって、Jyotish は、戻ってきたカルマを特定するだけでなく、その影響を軽減、修正、または方向転換する機能も提供します。[4]`, ko: `따라서 Jyotish는 되돌아오는 카르마를 식별할 수 있을 뿐만 아니라 카르마의 효과를 줄이거나 수정하거나 방향을 바꾸는 기능도 제공합니다.[4]`,} },
      { type: "heading", level: 3, text: { en: `6. Jyotish Astrology Came from G.O.D.`, hi: `6. ज्योतिष ईश्वर से आया है।`, ja: `6. ジョーティッシュは神から来たものです。`, ko: `6. Jyotish 점성술은 G.O.D에서 나왔습니다.`,} },
      { type: "paragraph", text: { en: `If you ask a Jyotish Astrologer about the origins of their discipline, they are likely to tell you that it came from G.O.D.`, hi: `यदि आप किसी ज्योतिषी से उनके अनुशासन की उत्पत्ति के बारे में पूछते हैं, तो वे आपको बताएंगे कि यह G.O.D से आया है।`, ja: `ジョーティッシュの占星術師に彼らの学問の起源について尋ねると、おそらくそれは神から来たものだと答えるでしょう。`, ko: `당신이 조티교 점성가에게 그들의 규율의 기원에 대해 묻는다면, 그들은 그것이 G.O.D에서 왔다고 말할 것입니다.`,} },
      { type: "paragraph", text: { en: `Here, G.O.D. stands for Generator, Operator and Destroyer, represented in the Vedic tradition by Brahma, Vishnu, and Shiva.`, hi: `यहाँ, भगवान जनरेटर, ऑपरेटर और विध्वंसक के लिए खड़ा है, जिसका प्रतिनिधित्व वैदिक परंपरा में ब्रह्मा, विष्णु और शिव द्वारा किया जाता है।`, ja: `ここで、G.O.D.ヴェーダの伝統ではブラフマー、ヴィシュヌ、シヴァによって表される、ジェネレーター、オペレーター、デストロイヤーの略です。`, ko: `여기, G.O.D. 베다 전통에서 브라흐마(Brahma), 비슈누(Vishnu), 시바(Shiva)로 대표되는 발전기(Generator), 조작자(Operator), 파괴자(Destroyer)를 의미합니다.`,} },
      { type: "paragraph", text: { en: `This concept represents a major distinction between Jyotish and Western Astrology.`, hi: `यह अवधारणा ज्योतिष और पश्चिमी ज्योतिष के बीच एक प्रमुख अंतर का प्रतिनिधित्व करती है।`, ja: `この概念は、ジョーティッシュと西洋占星術の大きな違いを表しています。`, ko: `이 개념은 Jyotish와 Western Astrology의 주요 차이점을 나타냅니다.`,} },
      { type: "paragraph", text: { en: `According to tradition, the knowledge of Jyotish was revealed or cognized. It was not invented, experimentally developed, or gradually refined over centuries by human beings.`, hi: `परंपरा के अनुसार ज्योतिष का ज्ञान प्रकट या ज्ञात हुआ। इसका आविष्कार, प्रयोगात्मक रूप से विकास या धीरे-धीरे सदियों से मनुष्यों द्वारा परिष्कृत नहीं किया गया था।`, ja: `伝統によれば、ジョーティッシュの知識は明らかにされ、または認識されました。それは人間によって発明されたものでも、実験的に開発されたものでも、何世紀にもわたって徐々に洗練されたものでもありません。`, ko: `전통에 따르면 Jyotish에 대한 지식이 공개되거나 인식되었습니다. 그것은 인간이 발명하거나, 실험적으로 개발하거나, 수세기에 걸쳐 점차적으로 개선된 것이 아닙니다.`,} },
      { type: "paragraph", text: { en: `Western thought offers no exact equivalent to this process. However, the same mechanism is also said to be responsible for the emergence of other Applied Vedic Sciences such as Ayurveda and Vastu.`, hi: `पश्चिमी विचार इस प्रक्रिया का कोई सटीक समकक्ष प्रस्तुत नहीं करता है। हालाँकि, यही तंत्र आयुर्वेद और वास्तु जैसे अन्य व्यावहारिक वैदिक विज्ञानों के उद्भव के लिए भी जिम्मेदार माना जाता है।`, ja: `西洋の思想には、このプロセスにまったく相当するものはありません。しかし、アーユルヴェーダやヴァストゥなどの他の応用ヴェーダ科学の出現にも同じメカニズムが関与していると言われています。`, ko: `서양 사상은 이 과정과 정확히 일치하는 것을 제공하지 않습니다. 그러나 동일한 메커니즘이 Ayurveda 및 Vastu와 같은 다른 응용 베다 과학의 출현에도 책임이 있다고 합니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "paragraph", text: { en: `[1] Sri Sri Ravi Shankar: The Daily Sutra (Art of Living Foundation – Indian NGO), 20th May 2003.`, hi: `[1] श्री श्री रविशंकर: द डेली सूत्र (आर्ट ऑफ लिविंग फाउंडेशन - इंडियन एनजीओ), 20 मई 2003।`, ja: `[1] Sri Sri Ravi Shankar: The Daily Sutra (Art of Living Foundation – インドの NGO)、2003 年 5 月 20 日。`, ko: `[1] Sri Sri Ravi Shankar: The Daily Sutra(살아있는 예술 재단 – 인도 NGO), 2003년 5월 20일.`,} },
      { type: "paragraph", text: { en: `[2] For example, in Jyotish, Mars is generally highly beneficial for a person with a Leo Ascendant, while often producing strongly challenging effects for someone with a Virgo Ascendant. Thus the same planet can signify positive outcomes for one individual and negative outcomes for another. This strongly suggests that we are dealing with an integrated field of information rather than a physical force emanating from the planet itself.`, hi: `[2] उदाहरण के लिए, ज्योतिष में, मंगल आम तौर पर सिंह लग्न वाले व्यक्ति के लिए अत्यधिक लाभकारी होता है, जबकि कन्या लग्न वाले व्यक्ति के लिए अक्सर अत्यधिक चुनौतीपूर्ण प्रभाव पैदा करता है। इस प्रकार एक ही ग्रह एक व्यक्ति के लिए सकारात्मक परिणाम और दूसरे के लिए नकारात्मक परिणाम का संकेत दे सकता है। यह दृढ़ता से सुझाव देता है कि हम ग्रह से निकलने वाली भौतिक शक्ति के बजाय सूचना के एक एकीकृत क्षेत्र के साथ काम कर रहे हैं।`, ja: `[2] たとえば、ジョーティッシュでは、火星は一般的に獅子座のアセンダントを持つ人にとって非常に有益ですが、乙女座のアセンダントを持つ人にとっては非常に困難な影響をもたらすことがよくあります。したがって、同じ惑星は、ある個人にとってはポジティブな結果を意味し、別の個人にとってはネガティブな結果を意味する可能性があります。これは、私たちが地球自体から発せられる物理的な力ではなく、統合された情報の分野を扱っていることを強く示唆しています。`, ko: `[2] 예를 들어, Jyotish에서 화성은 일반적으로 Leo Ascendant를 가진 사람에게 매우 유익한 반면, Virgo Ascendant를 가진 사람에게는 종종 매우 도전적인 효과를 생성합니다. 따라서 동일한 행성은 한 개인에게는 긍정적인 결과를, 다른 개인에게는 부정적인 결과를 의미할 수 있습니다. 이는 우리가 행성 자체에서 나오는 물리적 힘이 아니라 통합된 정보 장을 다루고 있음을 강력하게 시사합니다.`,} },
      { type: "paragraph", text: { en: `[3] Artha relates to wealth and prosperity in all forms, including money, children, knowledge, food, and health. Dharma concerns duty, character, right action, and activities aligned with natural law. Kama encompasses desire, relationships, sensory pleasures, and aspirations. Moksha relates to spiritual development and progress toward Self-realization.`, hi: `[3] अर्थ का संबंध धन, संतान, ज्ञान, भोजन और स्वास्थ्य सहित सभी रूपों में धन और समृद्धि से है। धर्म कर्तव्य, चरित्र, सही कार्य और प्राकृतिक कानून के अनुरूप गतिविधियों से संबंधित है। काम में इच्छा, रिश्ते, संवेदी सुख और आकांक्षाएं शामिल हैं। मोक्ष का संबंध आध्यात्मिक विकास और आत्म-साक्षात्कार की दिशा में प्रगति से है।`, ja: `[3] アルタは、お金、子供、知識、食べ物、健康など、あらゆる形の富と繁栄に関係します。ダルマは義務、性格、正しい行動、自然法に沿った活動に関係します。カーマには、欲望、人間関係、感覚的な喜び、願望が含まれます。モクシャは精神的な発達と自己実現に向けた進歩に関係しています。`, ko: `[3] Artha는 돈, 자녀, 지식, 음식, 건강을 포함한 모든 형태의 부와 번영과 관련이 있습니다. 달마는 자연법에 부합하는 의무, 성격, 올바른 행동 및 활동에 관한 것입니다. 카마는 욕망, 관계, 감각적 즐거움, 열망을 포괄합니다. 목샤(Moksha)는 영적 발전과 자아 실현을 향한 진보와 관련이 있습니다.`,} },
      { type: "paragraph", text: { en: `[4] Vedic ceremonies such as Yagnas, when performed correctly by enlightened pundits, are believed to alter returning karmas. Likewise, because the universe is regarded as an interconnected whole, gemstones associated with particular planets and Sanskrit mantras are considered effective methods for modifying karmic influences and harmonizing the laws of nature.`, hi: `[4] माना जाता है कि यज्ञ जैसे वैदिक समारोह, जब प्रबुद्ध पंडितों द्वारा सही ढंग से किए जाते हैं, तो वापस आने वाले कर्मों को बदल देते हैं। इसी तरह, क्योंकि ब्रह्मांड को एक दूसरे से जुड़ा हुआ माना जाता है, विशेष ग्रहों और संस्कृत मंत्रों से जुड़े रत्नों को कार्मिक प्रभावों को संशोधित करने और प्रकृति के नियमों में सामंजस्य स्थापित करने के लिए प्रभावी तरीके माना जाता है।`, ja: `[4] ヤグナスなどのヴェーダの儀式は、啓発された専門家によって正しく行われた場合、戻ってきたカルマを変えると信じられています。同様に、宇宙は相互につながった全体とみなされているため、特定の惑星に関連付けられた宝石やサンスクリット語のマントラは、カルマの影響を修正し、自然法則を調和させるための効果的な方法であると考えられています。`, ko: `[4] 야그나(Yagna)와 같은 베다 의식은 깨달은 전문가들이 올바르게 수행할 경우 카르마가 되돌아오는 것을 바꾸는 것으로 믿어집니다. 마찬가지로 우주는 상호 연결된 전체로 간주되기 때문에 특정 행성과 산스크리트어 만트라와 관련된 보석은 카르마의 영향을 수정하고 자연 법칙을 조화시키는 효과적인 방법으로 간주됩니다.`,} },
    ],
  },
  {
    id: "sidereal-zodiac-p3",
    section: "introduction",
    title: { en: `Jyotish – Sidereal Zodiac`, hi: `ज्योतिष - नाक्षत्र राशि चक्र`, ja: `ジョーティッシュ – 恒星黄道帯`, ko: `Jyotish – 항성 황도대`,},
    related: ["nakshatras-stellar-1","western-differences","paradigm-shift"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Sidereal Zodiac`, hi: `ज्योतिष - नाक्षत्र राशि चक्र`, ja: `ジョーティッシュ – 恒星黄道帯`, ko: `Jyotish – 항성 황도대`,} },
      { type: "paragraph", text: { en: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac. In doing so, it addresses one of the primary objections astronomers raise against astrology. The article also demonstrates how Sun signs, Ascendants, and all planetary positions can appear in different signs when calculated using the two systems.`, hi: `सारांश: यह लेख वैदिक ज्योतिष और पश्चिमी ज्योतिष में प्रयुक्त राशियों के बीच अंतर की पड़ताल करता है। यह बताता है कि ज्योतिष चल उष्णकटिबंधीय राशि चक्र के बजाय निश्चित नाक्षत्र राशि चक्र पर भरोसा क्यों करता है। ऐसा करने में, यह खगोलविदों द्वारा ज्योतिष के विरुद्ध उठाई गई प्राथमिक आपत्तियों में से एक को संबोधित करता है। लेख यह भी दर्शाता है कि दो प्रणालियों का उपयोग करके गणना करने पर सूर्य चिन्ह, लग्न और सभी ग्रहों की स्थिति अलग-अलग संकेतों में कैसे दिखाई दे सकती है।`, ja: `概要: この記事では、ヴェーダ占星術と西洋占星術で使用される黄道帯の違いについて説明します。これは、Jyotish が移動可能な Tropical Zodiac ではなく、固定された Sidereal Zodiac に依存している理由を説明しています。そうすることで、それは天文学者が占星術に対して提起する主な反対の 1 つに対処します。この記事では、2 つのシステムを使用して計算した場合に、太陽星座、アセンダント、およびすべての惑星の位置が異なる星座にどのように表示されるかについても説明します。`, ko: `요약: 이 기사에서는 베다 점성술과 서양 점성술에 사용되는 황도대 간의 차이점을 탐구합니다. 이는 Jyotish가 이동 가능한 열대 황도대보다는 고정된 항성 황도대에 의존하는 이유를 설명합니다. 그렇게 함으로써, 그것은 천문학자들이 점성술에 대해 제기하는 주요 반대 의견 중 하나를 다루고 있습니다. 이 기사는 또한 두 시스템을 사용하여 계산할 때 태양 별자리, 어센던트 및 모든 행성 위치가 어떻게 다른 별자리로 나타날 수 있는지 보여줍니다.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish Uses the Fixed Sidereal Zodiac`, hi: `ज्योतिष स्थिर नक्षत्र राशि चक्र का उपयोग करता है`, ja: `ジョーティッシュは固定恒星黄道帯を使用します`, ko: `Jyotish는 고정 항성 황도대를 사용합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish Astrology uses a different zodiac from the one employed in Western Astrology.`, hi: `ज्योतिष पश्चिमी ज्योतिष में प्रयुक्त राशि से भिन्न राशि का उपयोग करता है।`, ja: `ジョーティッシュでは、西洋占星術で使用される星座とは異なる星座が使用されます。`, ko: `Jyotish 점성술은 서양 점성술에서 사용되는 것과 다른 황도대를 사용합니다.`,} },
      { type: "paragraph", text: { en: `The zodiacs used by both Jyotish and Western Astrology are based upon an imaginary celestial sphere. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. Both systems also use the same zodiac sign names, such as Aries, Taurus, Gemini, and so forth. The Sun appears to move through each zodiac sign in approximately one month.`, hi: `ज्योतिष और पश्चिमी ज्योतिष दोनों द्वारा उपयोग की जाने वाली राशियाँ एक काल्पनिक खगोलीय क्षेत्र पर आधारित हैं। प्रत्येक प्रणाली में, इस गोले को नारंगी के खंडों की तरह, प्रत्येक 30 डिग्री के बारह बराबर खंडों में विभाजित किया गया है। दोनों प्रणालियाँ समान राशि चिन्ह नामों का भी उपयोग करती हैं, जैसे मेष, वृषभ, मिथुन, इत्यादि। ऐसा प्रतीत होता है कि सूर्य लगभग एक महीने में प्रत्येक राशि से होकर गुजरता है।`, ja: `ジョーティッシュと西洋占星術の両方で使用される黄道帯は、想像上の天球に基づいています。各システムでは、この球は、オレンジのセグメントとよく似た、それぞれ 30 度の 12 の等しいセクションに分割されます。どちらのシステムでも、牡羊座、おうし座、双子座などの同じ星座名が使用されます。太陽は約 1 か月かけて各星座を移動するように見えます。`, ko: `Jyotish와 Western Astrology에서 사용하는 황도대는 가상의 천구를 기반으로 합니다. 각 시스템에서 이 구는 오렌지 조각과 마찬가지로 각각 30도씩 동일한 12개의 섹션으로 나뉩니다. 두 시스템 모두 양자리, 황소자리, 쌍둥이자리 등과 같은 동일한 황도대 별자리 이름을 사용합니다. 태양은 대략 한 달에 걸쳐 각 황도대 별자리를 통과하는 것으로 보입니다.`,} },
      { type: "image", src: "/assets/002.webp", alt: { en: `The twelve zodiac signs on the celestial sphere`, hi: `आकाशीय मंडल पर बारह राशियाँ`, ja: `天球上の12の黄道十二宮`, ko: `천구의 열두 황도대 별자리`,} },
      eduImage(educationImages.zodiacWheel, {
        en: "Zodiac wheel with nakshatras in Jyotish", hi: "ज्योतिष में नक्षत्रों के साथ राशि चक्र", ja: "ジョーティッシュにおけるナクシャトラ付き黄道帯", ko: "Jyotish의 nakshatras가 있는 황도대 바퀴",
      }),
      { type: "paragraph", text: { en: `Jyotish uses the fixed Sidereal Zodiac. The term Sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently anchored using the background of the fixed stars within our galaxy as its reference point.[1] As a result, the zodiac signs remain forever fixed relative to the stellar constellations.`, hi: `ज्योतिष स्थिर नक्षत्र राशि चक्र का उपयोग करता है। नाक्षत्र शब्द का अर्थ है "सितारों के संबंध में।" नाक्षत्र राशि चक्र का प्रारंभिक बिंदु हमारी आकाशगंगा के भीतर स्थिर तारों की पृष्ठभूमि को इसके संदर्भ बिंदु के रूप में उपयोग करके स्थायी रूप से तय किया गया है।[1] परिणामस्वरूप, तारकीय नक्षत्रों के सापेक्ष राशियाँ सदैव स्थिर रहती हैं।`, ja: `Jyotish は固定の Sidereal Zodiac を使用します。 Sidereal という用語は「星に関して」を意味します。恒星黄道帯の開始点は、銀河内の恒星の背景を基準点として使用して永続的に固定されています。[1]その結果、黄道十二宮は星座に対して永遠に固定されたままになります。`, ko: `Jyotish는 고정된 Sidereal Zodiac을 사용합니다. Sidereal이라는 용어는 "별과 관련하여"를 의미합니다. 항성 황도대의 시작점은 우리 은하계 내의 항성 배경을 기준점으로 사용하여 영구적으로 고정되어 있습니다.[1] 결과적으로 황도대 별자리는 별의 별자리에 비해 영원히 고정된 상태로 유지됩니다.`,} },
      { type: "paragraph", text: { en: `Therefore, in Vedic Astrology, the beginning of the first sign, Aries, never changes position. Since Aries remains fixed, all of the remaining zodiac signs also stay permanently aligned with the distant background stars.`, hi: `इसलिए, वैदिक ज्योतिष में, पहली राशि मेष की शुरुआत कभी भी स्थिति नहीं बदलती है। चूँकि मेष राशि स्थिर रहती है, शेष सभी राशियाँ भी दूर के पृष्ठभूमि सितारों के साथ स्थायी रूप से संरेखित रहती हैं।`, ja: `したがって、ヴェーダ占星術では、最初の星座の始まりである牡羊座の位置が変わることはありません。牡羊座は固定されたままであるため、残りのすべての星座も遠くの背景の星と永久に整列したままになります。`, ko: `그러므로 베다 점성술에서 첫 번째 별자리인 양자리의 시작 부분은 결코 위치를 바꾸지 않습니다. 양자리는 고정되어 있기 때문에 나머지 황도대 별자리도 모두 멀리 있는 배경 별과 영구적으로 정렬되어 있습니다.`,} },
      { type: "paragraph", text: { en: `Western Astrology, by contrast, uses the movable Tropical Zodiac. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is referenced to the equinox. This movement occurs due to the astronomical phenomenon known as the precession of the equinoxes.[2]`, hi: `इसके विपरीत, पश्चिमी ज्योतिष, चल उष्णकटिबंधीय राशि चक्र का उपयोग करता है। इस राशि चक्र का प्रारंभिक बिंदु धीरे-धीरे स्थिर तारों की पृष्ठभूमि के सापेक्ष बदलता रहता है क्योंकि यह विषुव से संबंधित है। यह हलचल विषुव की पूर्वता नामक खगोलीय घटना के कारण होती है।[2]`, ja: `Western Astrology, by contrast, uses the movable Tropical Zodiac. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is referenced to the equinox.この動きは、春分点の歳差運動として知られる天文現象によって発生します [2]。`, ko: `대조적으로, 서양 점성술은 움직일 수 있는 열대 황도대를 사용합니다. 이 황도대의 시작점은 분점을 기준으로 하기 때문에 고정된 별의 배경을 기준으로 점차 이동합니다. 이러한 움직임은 분점 세차운동으로 알려진 천문학적 현상으로 인해 발생합니다.[2]`,} },
      { type: "paragraph", text: { en: `Consequently, in Western Astrology, the position associated with the sign Aries slowly moves through the sky against the background of the fixed stars. It is therefore not permanently linked to any specific stellar constellation. Many people—including students of Western Astrology—find this fact quite surprising.`, hi: `नतीजतन, पश्चिमी ज्योतिष में, मेष राशि से जुड़ी स्थिति धीरे-धीरे स्थिर तारों की पृष्ठभूमि के खिलाफ आकाश में घूमती है। इसलिए यह स्थायी रूप से किसी विशिष्ट तारकीय तारामंडल से जुड़ा नहीं है। कई लोगों को—जिनमें पश्चिमी ज्योतिष के छात्र भी शामिल हैं—यह तथ्य काफी आश्चर्यजनक लगता है।`, ja: `したがって、西洋占星術では、牡羊座に関連付けられた位置は恒星を背景にゆっくりと空を移動します。したがって、特定の星座と永続的に関連付けられているわけではありません。西洋占星術の学生を含む多くの人が、この事実を非常に驚くべきと感じています。`, ko: `결과적으로 서양 점성술에서는 양자리 별자리와 관련된 위치가 고정된 별을 배경으로 하늘을 통해 천천히 이동합니다. 따라서 특정 별의 별자리와 영구적으로 연결되어 있지 않습니다. 서양 점성술을 연구하는 학생들을 포함하여 많은 사람들은 이 사실을 매우 놀랍게 생각합니다.`,} },
      { type: "paragraph", text: { en: `Astronomers often criticize Western Astrology because it employs the movable Tropical Zodiac, meaning that the sign Aries changes its position relative to the stars over time. However, this criticism does not apply to Jyotish because Vedic Astrology uses a fixed zodiac rather than a moving one.`, hi: `खगोलशास्त्री अक्सर पश्चिमी ज्योतिष की आलोचना करते हैं क्योंकि यह चल उष्णकटिबंधीय राशि चक्र को नियोजित करता है, जिसका अर्थ है कि मेष राशि समय के साथ सितारों के सापेक्ष अपनी स्थिति बदलती है। हालाँकि, यह आलोचना ज्योतिष पर लागू नहीं होती क्योंकि वैदिक ज्योतिष चलित राशि के बजाय स्थिर राशि का उपयोग करता है।`, ja: `天文学者はしばしば西洋占星術を批判します。その理由は、西洋占星術では移動可能な熱帯黄道帯が採用されており、牡羊座が時間の経過とともに星に対する位置を変えることを意味します。ただし、ヴェーダ占星術では動く星座ではなく固定された星座を使用するため、この批判はジョーティッシュには当てはまりません。`, ko: `천문학자들은 서양 점성술이 움직일 수 있는 열대 황도대를 사용하기 때문에 종종 비판하는데, 이는 양자리 별자리가 시간이 지남에 따라 별에 대한 위치가 변한다는 것을 의미합니다. 그러나 베다 점성술은 움직이는 황도대가 아닌 고정된 황도대를 사용하기 때문에 이 비판은 조티쉬에는 적용되지 않습니다.`,} },
      { type: "heading", level: 3, text: { en: `Ayanamsa – Angular Difference Between the Two Zodiacs`, hi: `अयनांश - दो राशियों के बीच कोणीय अंतर`, ja: `アヤナムサ – 2 つの黄道帯の角度の違い`, ko: `Ayanamsa – 두 황도대 사이의 각도 차이`,} },
      { type: "paragraph", text: { en: `The angular difference between the Sidereal and Tropical zodiacs is known as the Ayanamsa (ayanāṃśa or ayanamsha), and this difference gradually increases over time.[3]`, hi: `नाक्षत्र और उष्णकटिबंधीय राशियों के बीच के कोणीय अंतर को अयनांश (अयनांश या अयनांश) के रूप में जाना जाता है, और यह अंतर समय के साथ धीरे-धीरे बढ़ता जाता है।[3]`, ja: `恒星黄道帯と熱帯黄道帯の間の角度の違いはアヤナムサ (ayanāṃśa または ayanamsha) として知られており、この差は時間の経過とともに徐々に大きくなります [3]。`, ko: `항성 황도대와 열대 황도대의 각도 차이는 Ayanamsa(ayanāṃśa 또는 ayanamsha)로 알려져 있으며, 이 차이는 시간이 지남에 따라 점차 증가합니다.[3]`,} },
      { type: "paragraph", text: { en: `Although the starting points of the two zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used in Western Astrology has steadily moved away from that original position.`, hi: `हालाँकि लगभग 1,700 साल पहले दोनों राशियों के शुरुआती बिंदु लगभग एक सीध में थे, लेकिन पश्चिमी ज्योतिष में प्रयुक्त उष्णकटिबंधीय राशि चक्र लगातार अपनी मूल स्थिति से दूर चला गया है।`, ja: `2 つの黄道帯の開始点は約 1,700 年前にほぼ一致していましたが、西洋占星術で使用されるトロピカル黄道帯は、その元の位置から着実に遠ざかっています。`, ko: `두 황도대의 시작점은 대략 1,700년 전쯤에 정렬되었지만, 서양 점성술에서 사용되는 열대 황도대는 꾸준히 원래 위치에서 멀어져 왔습니다.`,} },
      { type: "paragraph", text: { en: `As of 2021, the difference between the two systems is approximately 24 degrees. This means that if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will appear at approximately 5 degrees Virgo in the Sidereal Zodiac after subtracting the 24-degree Ayanamsa.`, hi: `2021 तक, दोनों प्रणालियों के बीच का अंतर लगभग 24 डिग्री है। इसका मतलब यह है कि यदि सूर्य उष्णकटिबंधीय राशि चक्र में 29 डिग्री कन्या राशि पर स्थित है, तो 24 डिग्री अयनांश को घटाने के बाद यह नक्षत्र राशि चक्र में लगभग 5 डिग्री कन्या राशि पर दिखाई देगा।`, ja: `2021 年現在、2 つのシステムの差は約 24 度です。これは、太陽が熱帯黄道帯の乙女座 29 度に位置する場合、24 度のアヤナムサを差し引いた後、恒星黄道帯の乙女座約 5 度に現れることを意味します。`, ko: `2021년 현재 두 시스템의 차이는 약 24도 정도이다. 즉, 태양이 열대 황도대에서 처녀자리 29도에 위치하면 아야남사 24도를 뺀 후 항성 황도대에서는 처녀자리 약 5도에 나타납니다.`,} },
      { type: "paragraph", text: { en: `In this example, the Sun remains in Virgo in both systems.`, hi: `इस उदाहरण में, सूर्य दोनों प्रणालियों में कन्या राशि में रहता है।`, ja: `この例では、太陽はどちらの星系でも乙女座に留まります。`, ko: `이 예에서 태양은 두 시스템 모두에서 처녀자리에 남아 있습니다.`,} },
      { type: "paragraph", text: { en: `However, if the Sun is located between 0 and 24 degrees Virgo in the Tropical Zodiac, it will move into Leo when calculated using the Sidereal Zodiac employed by Jyotish. In effect, the planet shifts backward (anti-clockwise) by the Ayanamsa value and enters the previous sign.[4]`, hi: `हालाँकि, यदि सूर्य उष्णकटिबंधीय राशि चक्र में 0 और 24 डिग्री कन्या राशि के बीच स्थित है, तो ज्योतिष द्वारा नियोजित नाक्षत्र राशि चक्र का उपयोग करके गणना करने पर यह सिंह राशि में चला जाएगा। वास्तव में, ग्रह अयनांश मान से पीछे की ओर (वामावर्त) स्थानांतरित हो जाता है और पिछली राशि में प्रवेश कर जाता है।[4]`, ja: `ただし、太陽が熱帯黄道帯の乙女座 0 度から 24 度の間に位置する場合、ジョーティッシュが使用する恒星黄道帯を使用して計算すると、太陽は獅子座に移動します。実際、惑星はアヤナムサ値だけ後方 (反時計回り) に移動し、前の符号に入ります。 [4]`, ko: `그러나 태양이 열대 황도대에서 처녀자리 0도에서 24도 사이에 위치하는 경우 Jyotish가 사용하는 항성 황도대를 사용하여 계산할 때 사자자리로 이동합니다. 실제로 행성은 Ayanamsa 값만큼 뒤로(시계 반대 방향) 이동하고 이전 기호로 들어갑니다.[4]`,} },
      { type: "paragraph", text: { en: `As a result, a person's Sun sign may differ depending on which zodiac is used. For example, an individual classified as a Virgo in Western Astrology may become a Leo in Jyotish.`, hi: `परिणामस्वरूप, किसी व्यक्ति की सूर्य राशि इस बात पर निर्भर हो सकती है कि कौन सी राशि का उपयोग किया जाता है। उदाहरण के लिए, पश्चिमी ज्योतिष में कन्या राशि का व्यक्ति ज्योतिष में सिंह राशि का हो सकता है।`, ja: `その結果、どの星座が使用されるかによって、人の太陽星座が異なる場合があります。たとえば、西洋占星術では乙女座として分類される個人が、ジョーティッシュでは獅子座になる可能性があります。`, ko: `결과적으로, 어떤 황도대를 사용하느냐에 따라 사람의 태양궁이 달라질 수 있습니다. 예를 들어, 서양 점성술에서 처녀자리로 분류된 개인은 Jyotish에서는 사자자리가 될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The same principle applies not only to the Sun but also to all other planets and to the Ascendant. These differences in planetary and Ascendant placements help explain many of the inconsistencies sometimes encountered in charts interpreted solely through the modern Western system.`, hi: `यही सिद्धांत न केवल सूर्य पर बल्कि अन्य सभी ग्रहों और लग्न पर भी लागू होता है। ग्रहों और लग्न स्थानों में ये अंतर आधुनिक पश्चिमी प्रणाली के माध्यम से व्याख्या किए गए चार्ट में कभी-कभी सामने आने वाली कई विसंगतियों को समझाने में मदद करते हैं।`, ja: `同じ原理が太陽だけでなく、他のすべての惑星やアセンダントにも当てはまります。惑星とアセンダントの配置におけるこれらの違いは、現代西洋のシステムのみを通じて解釈されたチャートで時々遭遇する矛盾の多くを説明するのに役立ちます。`, ko: `동일한 원리는 태양뿐만 아니라 다른 모든 행성과 승천에도 적용됩니다. 행성과 어센던트 배치의 이러한 차이는 현대 서양 시스템을 통해서만 해석된 차트에서 때때로 발생하는 많은 불일치를 설명하는 데 도움이 됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Nakshatras – ‘Stellar Constellations’`, hi: `नक्षत्र - 'तारकीय तारामंडल'`, ja: `ナクシャトラ – 「星の星座」`, ko: `낙샤트라 – '별의 별자리'`,} },
      { type: "paragraph", text: { en: `Jyotish places considerable importance on the Nakshatras, or stellar constellations, when interpreting birth charts, assessing compatibility, and determining auspicious timing through Muhurta.`, hi: `जन्म कुंडली की व्याख्या, अनुकूलता का आकलन और मुहूर्त के माध्यम से शुभ समय का निर्धारण करते समय ज्योतिष नक्षत्रों या तारकीय नक्षत्रों को काफी महत्व देता है।`, ja: `ジョーティッシュは、出生図を解釈し、互換性を評価し、ムフルタを通じて縁起の良いタイミングを判断する際に、ナクシャトラ、つまり星の星座を非常に重視します。`, ko: `Jyotish는 출생 차트를 해석하고, 호환성을 평가하고, Muhurta를 통해 상서로운 시기를 결정할 때 Nakshatras 또는 별 별자리에 상당한 중요성을 둡니다.`,} },
      { type: "paragraph", text: { en: `There are twenty-seven Nakshatras, sometimes referred to as Lunar Mansions, distributed evenly throughout the zodiac (more precisely, as equal divisions along the ecliptic).`, hi: `सत्ताईस नक्षत्र हैं, जिन्हें कभी-कभी चंद्र भवन भी कहा जाता है, जो पूरी राशि में समान रूप से वितरित होते हैं (अधिक सटीक रूप से, क्रांतिवृत्त के साथ समान विभाजन के रूप में)।`, ja: `月の邸宅とも呼ばれる 27 のナクシャトラがあり、黄道帯全体に均等に配置されています (より正確には、黄道に沿って均等に分割されています)。`, ko: `때로는 달의 저택(Lunar Mansions)이라고도 불리는 27개의 나크샤트라가 황도대 전체에 고르게 분포되어 있습니다(보다 정확하게는 황도를 따라 균등한 분할로).`,} },
      { type: "paragraph", text: { en: `Given the importance of the Nakshatras within Jyotish, it is hardly surprising that Vedic Astrology uses a zodiac that remains permanently aligned with both the fixed stars and the Nakshatra system.`, hi: `ज्योतिष में नक्षत्रों के महत्व को देखते हुए, यह कोई आश्चर्य की बात नहीं है कि वैदिक ज्योतिष एक ऐसी राशि का उपयोग करता है जो स्थिर सितारों और नक्षत्र प्रणाली दोनों के साथ स्थायी रूप से संरेखित रहती है।`, ja: `ジョーティッシュにおけるナクシャトラの重要性を考えると、ヴェーダ占星術が恒星とナクシャトラ体系の両方と永久に一致する黄道帯を使用することは驚くべきことではありません。`, ko: `Jyotish 내에서 Nakshatras의 중요성을 고려할 때, Vedic Astrology가 고정 별 및 Nakshatra 시스템 모두와 영구적으로 정렬된 상태로 유지되는 황도대를 사용하는 것은 놀라운 일이 아닙니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "paragraph", text: { en: `[1] The so-called "fixed stars" are located at such immense distances from Earth that their angular movement relative to our Sun is extremely small, even across thousands of years. For practical purposes, they can therefore be regarded as fixed or immovable reference points.`, hi: `[1] तथाकथित "स्थिर तारे" पृथ्वी से इतनी अधिक दूरी पर स्थित हैं कि हमारे सूर्य के सापेक्ष उनकी कोणीय गति, हजारों वर्षों में भी, बेहद छोटी है। व्यावहारिक उद्देश्यों के लिए, उन्हें निश्चित या अचल संदर्भ बिंदु माना जा सकता है।`, ja: `[1] いわゆる「恒星」は地球から非常に離れたところに位置しているため、太陽に対する角運動は数千年にわたっても非常に小さいです。したがって、実用的な目的では、それらは固定または不動の基準点と見なすことができます。`, ko: `[1] 소위 "고정별"은 지구로부터 너무 멀리 떨어져 있어 태양에 대한 각운동이 수천 년에 걸쳐 극히 작습니다. 따라서 실제적인 목적을 위해 고정되거나 움직일 수 없는 기준점으로 간주될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `[2] The equinox point on Earth's orbit around the Sun shifts relative to the background of the fixed stars because of the phenomenon known as the precession of the equinoxes. This occurs due to a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. One complete precessional cycle takes approximately 26,000 years.`, hi: `[2] सूर्य के चारों ओर पृथ्वी की कक्षा पर विषुव बिंदु स्थिर तारों की पृष्ठभूमि के सापेक्ष बदल जाता है, इस घटना के कारण जिसे विषुव की पूर्वता के रूप में जाना जाता है। यह पृथ्वी की घूर्णन धुरी में मामूली उतार-चढ़ाव के कारण होता है, जो घूमते हुए शीर्ष की गति के समान है, जिसकी धुरी धीरे-धीरे एक शंकु के आकार का पथ बनाती है। एक पूर्ण पूर्ववर्ती चक्र में लगभग 26,000 वर्ष लगते हैं।`, ja: `[2] 太陽の周りの地球の軌道上の春分点は、春分点の歳差運動として知られる現象により、恒星の背景に対して移動します。これは、地球の回転軸のわずかなぐらつきによって発生します。これは、軸がゆっくりと円錐形の軌道を描くコマの動きに似ています。 1 つの完全な歳差運動サイクルには約 26,000 年かかります。`, ko: `[2] 태양 주위를 도는 지구 궤도의 분점은 분점 세차 운동으로 알려진 현상으로 인해 고정된 별의 배경에 상대적으로 이동합니다. 이는 지구 회전축의 약간의 흔들림으로 인해 발생합니다. 이는 축이 원뿔 모양의 경로를 천천히 따라가는 회전하는 팽이의 움직임과 유사합니다. 하나의 완전한 세차주기는 약 26,000년이 걸립니다.`,} },
      { type: "paragraph", text: { en: `[3] As of 2021, the angular separation between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, derived by Lahiri, is widely accepted among Jyotish Astrologers, and most astrological tables use Lahiri Ayanamsa. The Tropical Zodiac moves relative to the Sidereal Zodiac by roughly one degree every 71 years. Although this annual shift is small, it accumulates significantly over long periods. Remarkably, ancient Egyptian astronomers observed this movement thousands of years ago.`, hi: `[3] 2021 तक, उष्णकटिबंधीय और नाक्षत्र राशियों के बीच कोणीय पृथक्करण लगभग 24 डिग्री है। लाहिड़ी द्वारा प्राप्त यह मान, ज्योतिषियों के बीच व्यापक रूप से स्वीकार किया जाता है, और अधिकांश ज्योतिषीय तालिकाएँ लाहिड़ी अयनांश का उपयोग करती हैं। उष्णकटिबंधीय राशि चक्र नक्षत्र राशि चक्र के सापेक्ष हर 71 वर्ष में लगभग एक डिग्री तक चलता है। हालाँकि यह वार्षिक बदलाव छोटा है, यह लंबी अवधि में महत्वपूर्ण रूप से जमा होता है। उल्लेखनीय रूप से, प्राचीन मिस्र के खगोलविदों ने हजारों साल पहले इस आंदोलन को देखा था।`, ja: `[3] 2021 年の時点で、熱帯黄道帯と恒星黄道帯の間の角度分離は約 24 度です。ラヒリによって導き出されたこの値はジョーティッシュ師の間で広く受け入れられており、ほとんどの占星術表ではラヒリ アヤナムサが使用されています。熱帯黄道帯は恒星黄道帯に対して 71 年ごとにおよそ 1 度移動します。この年間変動は小さいですが、長期にわたって大幅に蓄積されます。注目すべきことに、古代エジプトの天文学者はこの動きを数千年前に観察していました。`, ko: `[3] 2021년 현재, 열대 황도대와 항성 황도대 사이의 각도 분리는 약 24도입니다. Lahiri에서 파생된 이 값은 Jyotish 점성가들 사이에서 널리 받아들여지며 대부분의 점성술 테이블은 Lahiri Ayanamsa를 사용합니다. 열대 황도대는 항성 황도대에 비해 대략 71년마다 1도씩 이동합니다. 이러한 연간 변화는 작지만 장기간에 걸쳐 상당히 누적됩니다. 놀랍게도 고대 이집트 천문학자들은 수천 년 전에 이러한 움직임을 관찰했습니다.`,} },
      { type: "paragraph", text: { en: `[4] The current difference between the two zodiacs is approximately 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, subtracting the Ayanamsa gives 14 – 24 = –10 degrees Virgo in the Sidereal system. Since this falls before the beginning of Virgo, the Sun effectively moves backward into Leo and occupies 20 degrees Leo (–10 + 30 = 20).`, hi: `[4] दोनों राशियों के बीच वर्तमान अंतर लगभग 24 डिग्री है। उदाहरण के लिए, यदि पश्चिमी ज्योतिष में सूर्य 14 डिग्री कन्या राशि पर स्थित है, तो अयनांश को घटाने पर नाक्षत्र प्रणाली में 14 - 24 = -10 डिग्री कन्या राशि प्राप्त होती है। चूँकि यह कन्या राशि की शुरुआत से पहले पड़ता है, सूर्य प्रभावी रूप से सिंह राशि में पीछे की ओर बढ़ता है और 20 डिग्री सिंह (-10 + 30 = 20) पर कब्जा कर लेता है।`, ja: `[4] 現在の 2 つの黄道帯の差は約 24 度です。たとえば、太陽が西洋占星術で乙女座 14 度に位置する場合、アヤナムサを差し引くと、恒星系では 14 – 24 = 乙女座 –10 度になります。これは乙女座が始まる前に当たるため、太陽は事実上獅子座に後退し、獅子座 20 度 (-10 + 30 = 20) を占めます。`, ko: `[4] 두 황도대 사이의 현재 차이는 약 24도입니다. 예를 들어, 서양 점성술에서 태양이 처녀자리 14도에 위치하는 경우 Ayanamsa를 빼면 항성계에서는 처녀자리 14 – 24 = –10도가 됩니다. 이것이 처녀자리가 시작되기 이전이기 때문에 태양은 효과적으로 사자자리 쪽으로 뒤로 이동하여 사자자리 20도를 차지합니다(–10 + 30 = 20).`,} },
      { type: "paragraph", text: { en: `By contrast, if the Sun is at 28 degrees Virgo in the Tropical Zodiac, subtracting the Ayanamsa results in 4 degrees Virgo in the Sidereal Zodiac. In this case, the Sun has shifted backward but remains within the same sign.`, hi: `इसके विपरीत, यदि सूर्य उष्णकटिबंधीय राशि चक्र में 28 डिग्री कन्या राशि पर है, तो अयनांश को घटाने पर नक्षत्र राशि चक्र में 4 डिग्री कन्या राशि प्राप्त होती है। इस स्थिति में, सूर्य पीछे की ओर चला गया है लेकिन उसी राशि के भीतर रहता है।`, ja: `対照的に、太陽が熱帯黄道帯の乙女座 28 度にある場合、アヤナムサを差し引くと、恒星黄道帯では乙女座 4 度になります。この場合、太陽は後方に移動していますが、同じ星座内に留まります。`, ko: `대조적으로, 태양이 열대 황도대에서 처녀자리 28도에 있는 경우, 아야남사를 빼면 항성 황도대에서 처녀자리는 4도가 됩니다. 이 경우 태양은 뒤로 이동했지만 같은 별자리 내에 남아 있습니다.`,} },
    ],
  }
];
